                                <button 
                                    onClick={handleDocBack} 
                                    className="p-2 -ml-2 rounded-full hover:bg-stone-100 dark:hover:bg-stone-800 transition-all duration-300 text-stone-600 dark:text-stone-300"
                                >
                                    <Icons.Back className="w-6 h-6" />
