import React, { useState } from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';
import { STATIC_BACKGROUNDS, DYNAMIC_BACKGROUNDS, NUMBER_COLORS, SKILLS, SOUND_PACKS } from '../../utils/constants';
import { AnimatedNumber } from '../ui/AnimatedNumber';

interface StoreScreenProps {
    points: number;
    onBack: () => void;
    purchasedSkills: string[];
    enabledSkills: string[];
    purchasedBackgrounds: string[];
    purchasedNumberColors: string[];
    purchasedSoundPacks: string[];
    selectedBackgroundId: string | null;
    selectedNumberColorId: string;
    selectedSoundPackId: string;
    onPurchase: (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => void;
    onSelectBackground: (id: string) => void;
    onSelectNumberColor: (id: string) => void;
    onSelectSoundPack: (id: string) => void;
    onToggleSkill: (id: string) => void;
}

export const StoreScreen: React.FC<StoreScreenProps> = ({
    points,
    onBack,
    purchasedSkills,
    enabledSkills,
    purchasedBackgrounds,
    purchasedNumberColors,
    purchasedSoundPacks,
    selectedBackgroundId,
    selectedNumberColorId,
    selectedSoundPackId,
    onPurchase,
    onSelectBackground,
    onSelectNumberColor,
    onSelectSoundPack,
    onToggleSkill
}) => {
    const [activeInfoId, setActiveInfoId] = useState<string | null>(null);
    const [isClosing, setIsClosing] = useState(false);

    const handleCloseInfo = () => {
        if (!activeInfoId) return;
        setIsClosing(true);
        setTimeout(() => {
            setActiveInfoId(null);
            setIsClosing(false);
        }, 150);
    };

    const handleSoundPackClick = (e: React.MouseEvent, pack: typeof SOUND_PACKS[0]) => {
        e.stopPropagation();
        const isPurchased = purchasedSoundPacks.includes(pack.id);

        // Preview the sound whenever clicked
        sounds.playPreview(pack.id);

        if (!isPurchased) {
            onPurchase(pack, 'sound');
        } else {
            // Select the pack
            onSelectSoundPack(pack.id);

            // Toggle Info Bubble logic
            if (activeInfoId === pack.id) {
                handleCloseInfo();
            } else {
                setActiveInfoId(pack.id);
                setIsClosing(false);
            }
        }
    };

    const handleSkillInteraction = (e: React.MouseEvent, skill: typeof SKILLS[0]) => {
        const isPurchased = purchasedSkills.includes(skill.id);
        if (!isPurchased) {
            onPurchase(skill, 'skill');
        } else {
            sounds.playClick();
            onToggleSkill(skill.id);
        }
    };

    // Shared Price Footer component for grid items
    const ItemFooter = ({ isPurchased, isSelected, cost }: any) => {
        // If not purchased, always show price
        if (!isPurchased) {
            return (
                <div className="h-6 bg-white dark:bg-stone-800 border-t border-stone-200 dark:border-stone-700 flex items-center justify-center gap-0.5 shrink-0 relative z-10">
                    <span className="text-[13px] font-bold text-stone-900 dark:text-white leading-none pt-0.5">{cost}</span>
                    <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current" />
                </div>
            );
        }
        // Return null when purchased to allow content to center naturally
        return null;
    };

    return (
        <div 
            className="flex-1 w-full flex flex-col items-center overflow-hidden"
            onClick={handleCloseInfo}
        >
             {/* Locked Header */}
             <div className="w-full max-w-md flex items-center justify-between px-6 pt-4 pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Store</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Personalize</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm relative z-30">
                      <AnimatedNumber value={points} className="text-sm font-bold text-t-primary tabular-nums" />
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                </div>
             </div>

             <div className="flex-1 w-full overflow-y-auto overflow-x-hidden px-6 pb-6 hide-scrollbar flex flex-col items-center">
                  <div className="w-full max-w-md space-y-10 pt-2">

                      {/* SKILLS SECTION - Redesigned List View (Compact) */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Skills</h2>
                          <div className="flex flex-col gap-3">
                              {SKILLS.map(skill => {
                                  const isPurchased = purchasedSkills.includes(skill.id);
                                  const isEnabled = enabledSkills.includes(skill.id);
                                  const SkillIcon = skill.icon;

                                  return (
                                      <button 
                                          key={skill.id}
                                          onClick={(e) => handleSkillInteraction(e, skill)}
                                          className={`w-full p-3 rounded-3xl shadow-sm flex items-center gap-3.5 text-left active:scale-[0.98] transition-all bg-t-surface relative overflow-hidden group`}
                                      >
                                          {/* Icon Box - Smaller */}
                                          <div className={`w-14 h-14 rounded-xl flex items-center justify-center shrink-0 ${skill.bgClass} transition-transform group-active:scale-95`}>
                                              <SkillIcon className={`w-7 h-7 ${skill.class}`} />
                                          </div>

                                          {/* Text Content */}
                                          <div className="flex-1 min-w-0 py-0.5">
                                              <h3 className="text-lg font-bold text-t-primary leading-tight mb-1">{skill.name}</h3>
                                              <p className="text-[11px] font-medium text-t-secondary leading-snug">{skill.description}</p>
                                          </div>

                                          {/* Action Area */}
                                          <div className="shrink-0 pl-1">
                                              {isPurchased ? (
                                                   // Toggle UI
                                                   <div className={`w-12 h-7 rounded-full p-1 transition-colors duration-300 ease-out ${isEnabled ? 'bg-stone-600 dark:bg-stone-400' : 'bg-stone-300 dark:bg-stone-700'}`}>
                                                       <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform duration-300 ease-out ${isEnabled ? 'translate-x-5' : 'translate-x-0'}`} />
                                                   </div>
                                              ) : (
                                                   // Price UI
                                                   <div className="flex flex-col items-center justify-center bg-stone-100 dark:bg-stone-800 border border-stone-200 dark:border-stone-700 px-3 py-2 rounded-xl min-w-[60px]">
                                                       <span className="text-sm font-bold text-t-primary leading-none">{skill.cost}</span>
                                                       <Icons.Diamond className="w-3 h-3 text-blue-500 fill-current mt-0.5" />
                                                   </div>
                                              )}
                                          </div>
                                      </button>
                                  );
                              })}
                          </div>
                      </div>

                      {/* BACKGROUNDS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Backgrounds</h2>
                          <div className="mb-6">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Static</h3>
                              <div className="grid grid-cols-5 gap-2 items-start">{STATIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1.5">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-gradient-to-t from-stone-200 to-white dark:bg-stone-800 ${isSelected ? 'border border-stone-600 dark:border-stone-400 scale-105 z-10' : ''}`}
                                          >
                                              <div className={`flex-1 relative overflow-hidden ${bg.class}`}>
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: bg.id === 'bg-default' ? 'calc(var(--overlay-opacity) * 0.6)' : 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                          <div className="mb-2">
                              <h3 className="text-xs font-bold text-t-secondary uppercase tracking-widest mb-3 ml-1">Atmosphere</h3>
                              <div className="grid grid-cols-5 gap-2 items-start">{DYNAMIC_BACKGROUNDS.map(bg => {
                                  const isPurchased = purchasedBackgrounds.includes(bg.id);
                                  const isSelected = selectedBackgroundId === bg.id;
                                  return (
                                      <div key={bg.id} className="flex flex-col items-center gap-1.5">
                                          <button 
                                              onClick={() => isPurchased ? onSelectBackground(bg.id) : onPurchase(bg, 'bg')} 
                                              className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all active:scale-95 bg-gradient-to-t from-stone-200 to-white dark:bg-stone-800 ${isSelected ? 'border border-stone-600 dark:border-stone-400 scale-105 z-10' : ''}`}
                                          >
                                              <div 
                                                className={`flex-1 relative overflow-hidden ${bg.class}`} 
                                                style={{ backgroundSize: '300% 300%' }} // Increased scale for preview to enhance visible movement (300%)
                                              >
                                                   <div className="absolute inset-0 bg-black pointer-events-none transition-opacity duration-500" style={{ opacity: 'calc(var(--overlay-opacity) * 1.6)' }} />
                                              </div>
                                              <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={bg.cost} />
                                          </button>
                                          <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{bg.name}</span>
                                      </div>
                                  );
                              })}</div>
                          </div>
                      </div>

                      {/* SOUND PACKS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Sound Packs</h2>
                          <div className="grid grid-cols-5 gap-2 items-start">{SOUND_PACKS.map(pack => {
                              const isPurchased = purchasedSoundPacks.includes(pack.id);
                              const isSelected = selectedSoundPackId === pack.id;
                              const isInfoActive = activeInfoId === pack.id;
                              const PackIcon = pack.icon;

                              return (
                                  <div key={pack.id} className={`flex flex-col items-center gap-1.5 ${isSelected ? 'relative z-20' : 'relative z-0'}`}>
                                      {/* Info Bubble - Positioned relative to main container */}
                                      {isInfoActive && (
                                          <div className="absolute left-1/2 -translate-x-1/2 -top-2 -translate-y-full w-32 pointer-events-none z-50">
                                              <div className={`origin-bottom ${isClosing ? 'animate-tooltip-exit' : 'animate-tooltip-enter'}`}>
                                                  <div className="bg-stone-800 text-white dark:bg-white dark:text-stone-900 text-[10px] p-2 rounded-lg shadow-xl text-center font-medium leading-tight relative border border-stone-600/30">
                                                      {pack.description}
                                                      {/* Arrow */}
                                                      <div className="absolute top-full left-1/2 -translate-x-1/2 w-0 h-0 border-4 border-transparent border-t-stone-800 dark:border-t-white"></div>
                                                  </div>
                                              </div>
                                          </div>
                                      )}

                                      <button 
                                          onClick={(e) => handleSoundPackClick(e, pack)} 
                                          className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all bg-gradient-to-t from-stone-100 to-white dark:bg-stone-800 ${isSelected ? 'border border-stone-600 dark:border-stone-400 scale-105 shadow-md' : 'active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center relative z-10 overflow-hidden`}>
                                              <PackIcon className={`w-8 h-8 ${pack.iconColor} relative z-20`} />
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={pack.cost} />
                                      </button>

                                      <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{pack.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>

                      {/* NUMBER COLORS */}
                      <div>
                          <h2 className="text-lg font-bold text-t-primary mb-4 ml-1">Number Styles</h2>
                          <div className="grid grid-cols-5 gap-2 items-start">{NUMBER_COLORS.map(num => {
                              const isPurchased = purchasedNumberColors.includes(num.id);
                              const isSelected = selectedNumberColorId === num.id;
                              return (
                                  <div key={num.id} className="flex flex-col items-center gap-1.5">
                                      <button 
                                          onClick={() => isPurchased ? onSelectNumberColor(num.id) : onPurchase(num, 'num')} 
                                          className={`w-full aspect-square rounded-2xl shadow-sm flex flex-col items-stretch relative overflow-hidden transition-all bg-gradient-to-t from-stone-100 to-white dark:bg-stone-800 ${isSelected ? 'border border-stone-600 dark:border-stone-400 scale-105 z-10' : 'active:scale-95'}`}
                                      >
                                          <div className={`flex-1 flex items-center justify-center w-full`}>
                                              <span className={`text-3xl font-bold ${num.uiClass}`}>5</span>
                                          </div>
                                          <ItemFooter isPurchased={isPurchased} isSelected={isSelected} cost={num.cost} />
                                      </button>
                                      <span className={`text-[10px] font-bold text-center truncate w-full ${isSelected ? 'text-stone-800 dark:text-stone-200' : 'text-t-secondary'}`}>{num.name}</span>
                                  </div>
                              );
                          })}</div>
                      </div>
                  </div>
                  <div className="h-safe-bottom w-full shrink-0" />
             </div>
        </div>
    );
};

{/* Center Column: Title & Timer - Absolute Centered */}
<div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
    {settings.showTimer ? (
        <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
    ) : (
        <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
    )}
    <span className="text-[10px] font-bold text-stone-600 dark:text-stone-400 uppercase tracking-widest mt-1">
      {difficulty} {settings.showTimer && `• ${levelId}`}
    </span>
</div>

import React, { useState, useEffect, useCallback } from 'react';
import { Difficulty, AppSettings, Board, MoveLogEntry } from '../types';
import { Icons } from './ui/Icons';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameTimer } from '../hooks/useGameTimer';
import { useGameSkills } from '../hooks/useGameSkills';
import { formatTimeShort, getDifficultyPoints } from '../utils/constants';
import { Storage } from '../utils/storage';
import { generateReplayVideo } from '../utils/replay';
import { sounds } from '../utils/sound';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
    const [isPaused, setIsPaused] = useState(false);
    const [isCompleted, setIsCompleted] = useState(false);
    const [isEnding, setIsEnding] = useState(false);
    const [pointsEarned, setPointsEarned] = useState(0);

    // Replay State
    const [replayUrl, setReplayUrl] = useState<string | null>(null);
    const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
    const [showReplay, setShowReplay] = useState(false);

    // Animation State
    const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());

    // Load initial progress
    const [initialTime, setInitialTime] = useState(0);
    const [isLoaded, setIsLoaded] = useState(false);

    // Completion Data Buffer (to handle effects after render)
    const [completionData, setCompletionData] = useState<{board: Board, log: MoveLogEntry[], perfect: boolean} | null>(null);

    useEffect(() => {
        const progress = Storage.getLevelProgress(difficulty, levelId);
        if (progress) {
             setInitialTime(progress.timeElapsed);
        }
        setIsLoaded(true);
    }, [difficulty, levelId]);

    // Timer Hook
    const { timer, setTimer } = useGameTimer(settings, isPaused, isCompleted, isEnding, isSettingsOpen, initialTime);

    // Handlers
    const handleSaveProgress = useCallback((boardToSave: Board, scanUses?: number, revealUses?: number, currentMoveLog?: MoveLogEntry[]) => {
        Storage.saveLevelProgress({
            levelId,
            difficulty,
            status: 'in-progress',
            timeElapsed: timer,
            lastPlayed: Date.now(),
            boardState: boardToSave,
            scanUses,
            revealUses,
            moveLog: currentMoveLog
        });
    }, [difficulty, levelId, timer]);

    const handleBoardChange = useCallback((newBoard: Board, currentMoveLog: MoveLogEntry[]) => {
        // Optional: Auto-save on every move could be added here if needed
    }, []);

    const handleSectionComplete = useCallback((sections: string[]) => {
        setAnimatingSections(prev => {
            const next = new Set(prev);
            sections.forEach(s => next.add(s));
            return next;
        });

        sounds.playPop();

        setTimeout(() => {
            setAnimatingSections(prev => {
                const next = new Set(prev);
                sections.forEach(s => next.delete(s));
                return next;
            });
        }, 1000);
    }, []);

    const handleGameComplete = useCallback((completedBoard: Board, moveLog: MoveLogEntry[], isPerfect: boolean) => {
        setCompletionData({ board: completedBoard, log: [...moveLog], perfect: isPerfect });
    }, []);

    // Board Hook
    const {
        board,
        setBoard,
        solvedBoard,
        initialBoardRef,
        history,
        setHistory,
        moveLog,
        isPencilMode,
        setIsPencilMode,
        selectedCell,
        setSelectedCell,
        activeNumber,
        setActiveNumber,
        conflicts,
        numberCounts,
        initializeBoard,
        handleCellClick,
        handleNumberInput,
        handleUndo,
        handleErase,
        checkCompletion,
        removeNotesFromPeers
    } = useSudokuBoard({
        difficulty,
        levelId,
        settings,
        onBoardChange: handleBoardChange,
        onComplete: handleGameComplete,
        onSectionComplete: handleSectionComplete
    });

    // Skills Hook
    const {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        handleAutoFill,
        handleScan,
        handleReveal
    } = useGameSkills({
        board,
        setBoard,
        solvedBoard,
        selectedCell,
        activeNumber,
        settings,
        difficulty,
        removeNotesFromPeers,
        checkCompletion,
        onSaveProgress: handleSaveProgress,
        onSectionComplete: handleSectionComplete,
        timer,
        setHistory,
        moveLog
    });

    // Initialize Board Effect
    useEffect(() => {
        if (!isLoaded) return;
        const progress = Storage.getLevelProgress(difficulty, levelId);
        initializeBoard(progress?.boardState, progress?.moveLog);
        if (progress) {
             if (progress.scanUses !== undefined) setScanUses(progress.scanUses);
             if (progress.revealUses !== undefined) setRevealUses(progress.revealUses);
        }
    }, [isLoaded, difficulty, levelId, initializeBoard]);

    // Save on unmount
    useEffect(() => {
        return () => {
             if (!isCompleted && board.length > 0) {
                 handleSaveProgress(board, scanUses, revealUses, moveLog.current);
             }
        };
    }, [board, scanUses, revealUses, isCompleted, handleSaveProgress]);

    // Handle Completion Effect
    useEffect(() => {
        if (completionData && !isCompleted) {
             const { board: cBoard, log, perfect } = completionData;
             setIsCompleted(true);
             setIsEnding(true);
             sounds.playWin();

             Storage.saveLevelProgress({
                levelId,
                difficulty,
                status: 'completed',
                timeElapsed: timer,
                lastPlayed: Date.now(),
                boardState: cBoard,
                moveLog: log
            }, perfect);

             const pts = getDifficultyPoints(difficulty);
             setPointsEarned(pts);
             onEarnPoints(pts);
             onComplete();

             if (settings.generateReplay && initialBoardRef.current) {
                 setIsGeneratingReplay(true);
                 const moves = log.map(m => ({ row: m.r, col: m.c, value: m.v, t: m.t }));
                 const isDark = document.documentElement.classList.contains('dark');
                 generateReplayVideo(
                     initialBoardRef.current,
                     moves,
                     difficulty,
                     levelId,
                     isDark,
                     timer
                 ).then(url => {
                     setReplayUrl(url);
                     setIsGeneratingReplay(false);
                 });
             }
        }
    }, [completionData, isCompleted, settings.generateReplay, difficulty, levelId, timer, onEarnPoints, onComplete, initialBoardRef]);

    const generateReplay = () => {
        if (!initialBoardRef.current) return;
        setIsGeneratingReplay(true);
        const moves = moveLog.current.map(m => ({ row: m.r, col: m.c, value: m.v, t: m.t }));
        const isDark = document.documentElement.classList.contains('dark');
        generateReplayVideo(
            initialBoardRef.current,
            moves,
            difficulty,
            levelId,
            isDark,
            timer
        ).then(url => {
            setReplayUrl(url);
            setIsGeneratingReplay(false);
            if (url) setShowReplay(true);
        });
    };

    const handleShareReplay = async () => {
        if (replayUrl) {
            try {
                const blob = await fetch(replayUrl).then(r => r.blob());
                const file = new File([blob], `oku_replay_level_${levelId}.mp4`, { type: 'video/mp4' });
                if (navigator.share && navigator.canShare({ files: [file] })) {
                    await navigator.share({
                        files: [file],
                        title: 'Oku Sudoku Replay',
                        text: `Watch my solution for Level ${levelId} on ${difficulty}!`,
                    });
                } else {
                     const a = document.createElement('a');
                     a.href = replayUrl;
                     a.download = `oku_replay_level_${levelId}.mp4`;
                     a.click();
                }
            } catch (e) {
                console.error("Share failed", e);
            }
        }
    };

    if (!isLoaded) return <div />;

    return (
        <>
            <div className="flex-1 w-full flex flex-col items-center overflow-hidden relative">

                {/* Top Bar */}
                <div className="w-full max-w-md flex items-center justify-between px-4 pt-4 pb-2 relative shrink-0 z-20">
                     <button onClick={() => { sounds.playClick(); onBack(); }} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition text-t-icon relative z-30">
                        <Icons.Back className="w-6 h-6" />
                     </button>

                     <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                          {settings.showTimer ? (
                              <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                          ) : (
                              <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                          )}
                          <span className="text-[10px] font-bold text-stone-600 dark:text-stone-400 uppercase tracking-widest mt-1">
                            {difficulty} {settings.showTimer && `• ${levelId}`}
                          </span>
                     </div>

                     <div className="flex items-center gap-2 relative z-30">
                          <button onClick={() => { sounds.playClick(); setIsPaused(!isPaused); }} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition text-t-icon">
                              {isPaused ? <Icons.Play className="w-6 h-6" /> : <Icons.Pause className="w-6 h-6" />}
                          </button>
                          <button onClick={() => { sounds.playClick(); onSettingsOpen(); }} className="p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 transition text-t-icon">
                              <Icons.Settings className="w-6 h-6" />
                          </button>
                     </div>
                </div>

                {/* Game Area */}
                <div className={`flex-1 w-full overflow-hidden flex flex-col items-center justify-start relative ${isPaused ? 'opacity-0' : 'opacity-100'} transition-opacity duration-300`}>

                     <SudokuGrid 
                         board={board}
                         selectedCell={selectedCell}
                         activeNumber={activeNumber}
                         conflicts={conflicts}
                         revealingCell={revealingCell}
                         animatingCell={animatingCell}
                         isScanning={isScanning}
                         animatingSections={animatingSections}
                         settings={settings}
                         numberColor={numberColor}
                         onCellClick={(e, r, c) => handleCellClick(r, c, isPaused, isCompleted)}
                     />

                     {/* Controls & Numpad */}
                     <div className="w-full max-w-md px-4 pb-safe-bottom flex flex-col gap-4 mt-auto mb-2">
                          <GameControls 
                              canUndo={history.length > 0}
                              canErase={!!selectedCell && !board[selectedCell[0]][selectedCell[1]].isFixed}
                              isPencilMode={isPencilMode}
                              onUndo={(e) => { e.stopPropagation(); handleUndo(isPaused, isCompleted); }}
                              onErase={(e) => { e.stopPropagation(); handleErase(isPaused, isCompleted); }}
                              onTogglePencil={(e) => { e.stopPropagation(); sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                              purchasedSkills={purchasedSkills}
                              isAutoAvailable={isAutoAvailable}
                              scanUses={scanUses}
                              isScanning={isScanning}
                              scanCooldown={scanCooldown}
                              revealUses={revealUses}
                              revealingCell={revealingCell}
                              onAutoFill={(e) => { e.stopPropagation(); handleAutoFill(purchasedSkills); }}
                              onScan={(e) => { e.stopPropagation(); handleScan(isPaused, isCompleted); }}
                              onReveal={(e) => { e.stopPropagation(); handleReveal(isPaused, isCompleted); }}
                              timer={timer}
                          />

                          <NumberPad 
                              activeNumber={activeNumber}
                              numberCounts={numberCounts}
                              isPencilMode={isPencilMode}
                              numberColor={numberColor}
                              onNumberClick={(e, num) => { e.stopPropagation(); handleNumberInput(num, isPaused, isCompleted); }}
                          />
                     </div>
                </div>

                {/* Pause Overlay */}
                {isPaused && (
                    <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/80 dark:bg-black/80 backdrop-blur-sm">
                        <div className="flex flex-col items-center gap-6 animate-pop">
                            <div className="w-20 h-20 bg-stone-200 dark:bg-stone-700 rounded-full flex items-center justify-center">
                                <Icons.Pause className="w-10 h-10 text-stone-500 dark:text-stone-300 fill-current" />
                            </div>
                            <h2 className="text-3xl font-bold text-t-primary">Paused</h2>
                            <button 
                                onClick={() => { sounds.playClick(); setIsPaused(false); }}
                                className="px-8 py-3 bg-blue-500 text-white rounded-full font-bold shadow-lg active:scale-95 transition"
                            >
                                Resume
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Win Modal */}
            {isCompleted && (
                <WinModal 
                    difficulty={difficulty}
                    levelId={levelId}
                    timer={timer}
                    points={pointsEarned}
                    isGeneratingReplay={isGeneratingReplay}
                    replayUrl={replayUrl}
                    showReplay={showReplay}
                    generateReplayEnabled={settings.generateReplay}
                    onReplay={(e) => { e.stopPropagation(); sounds.playClick(); setShowReplay(true); }}
                    onShareReplay={handleShareReplay}
                    onCloseReplay={() => setShowReplay(false)}
                    onGenerateReplay={(e) => { e.stopPropagation(); sounds.playClick(); generateReplay(); }}
                    onBack={onBack}
                    onReturnToMenu={onReturnToMenu}
                />
            )}
        </>
    );
};

{/* Center Column: Title & Timer - Absolute Centered */}
<div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
    {settings.showTimer ? (
        <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
    ) : (
        <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
    )}
    <span className="text-[10px] font-bold text-stone-600 dark:text-stone-400 uppercase tracking-widest mt-1">
