import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board, MoveLogEntry } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameTimer } from '../hooks/useGameTimer';
import { useGameSkills } from '../hooks/useGameSkills';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { formatTimeShort, getDifficultyPoints } from '../utils/constants';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { Icons } from './ui/Icons';
import { AnimatedNumber } from './ui/AnimatedNumber';
import { generateReplayVideo } from '../utils/replay';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills,
}) => {
    // State
    const [isCompleted, setIsCompleted] = useState(false);
    const [showWinModal, setShowWinModal] = useState(false);
    const [pointsEarned, setPointsEarned] = useState(0);
    const [replayUrl, setReplayUrl] = useState<string | null>(null);
    const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
    const [showReplay, setShowReplay] = useState(false);
    const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());

    // Load initial data
    const savedProgress = Storage.getLevelProgress(difficulty, levelId);
    const initialTime = savedProgress?.timeElapsed || 0;

    // Timer Hook
    const { timer, setTimer } = useGameTimer(settings, false, isCompleted, false, isSettingsOpen, initialTime);

    // Timer Ref for stable callbacks
    const timerRef = useRef(timer);
    useEffect(() => { timerRef.current = timer; }, [timer]);

    // Persist Progress Function (Stable)
    const saveProgress = useCallback((currentBoard: Board, currentScanUses?: number, currentRevealUses?: number, currentMoveLog?: MoveLogEntry[]) => {
        if (isCompleted) return;

        Storage.saveLevelProgress({
            levelId,
            difficulty,
            status: 'in-progress',
            timeElapsed: timerRef.current,
            lastPlayed: Date.now(),
            boardState: currentBoard,
            moveLog: currentMoveLog,
            scanUses: currentScanUses,
            revealUses: currentRevealUses
        });
    }, [difficulty, levelId, isCompleted]);

    const handleSectionComplete = useCallback((sections: string[]) => {
         sounds.playPop();
         const newSet = new Set(sections);
         setAnimatingSections(newSet);
         setTimeout(() => {
             setAnimatingSections(new Set());
         }, 1000);
    }, []);

    // Board Hook
    const {
        board,
        setBoard,
        solvedBoard,
        initialBoardRef,
        history,
        setHistory,
        moveLog,
        isPencilMode,
        setIsPencilMode,
        selectedCell,
        setSelectedCell,
        activeNumber,
        setActiveNumber,
        conflicts,
        numberCounts,
        initializeBoard,
        handleCellClick,
        handleNumberInput,
        handleUndo,
        handleErase,
        checkCompletion,
        removeNotesFromPeers
    } = useSudokuBoard({
        difficulty,
        levelId,
        settings,
        onBoardChange: (newBoard, newLog) => saveProgress(newBoard, undefined, undefined, newLog),
        onComplete: (completedBoard, log, isPerfect) => {
            if (isCompleted) return;
            setIsCompleted(true);
            const points = getDifficultyPoints(difficulty);
            setPointsEarned(points);
            onEarnPoints(points);
            onComplete(); // Notify parent

            Storage.saveLevelProgress({
                levelId,
                difficulty,
                status: 'completed',
                timeElapsed: timerRef.current,
                lastPlayed: Date.now(),
                boardState: completedBoard,
                moveLog: log,
                scanUses: undefined,
                revealUses: undefined
            }, isPerfect);

            sounds.playWin();
            setTimeout(() => setShowWinModal(true), 1500);
        },
        onSectionComplete: handleSectionComplete
    });

    // Skills Hook
    const {
        scanUses,
        setScanUses,
        isScanning,
        scanCooldown,
        revealUses,
        setRevealUses,
        revealingCell,
        setRevealingCell,
        animatingCell,
        setAnimatingCell,
        isAutoAvailable,
        handleAutoFill,
        handleScan,
        handleReveal
    } = useGameSkills({
        board,
        setBoard,
        solvedBoard,
        setHistory,
        moveLog,
        selectedCell,
        activeNumber,
        settings,
        difficulty,
        removeNotesFromPeers,
        checkCompletion,
        onSaveProgress: (b, s, r, l) => saveProgress(b, s, r, l),
        onSectionComplete: handleSectionComplete,
        timer
    });

    // Initialize board effect
    useEffect(() => {
        if (savedProgress && savedProgress.status === 'in-progress' && savedProgress.boardState) {
             initializeBoard(savedProgress.boardState, savedProgress.moveLog);
             if (savedProgress.scanUses !== undefined) setScanUses(savedProgress.scanUses);
             if (savedProgress.revealUses !== undefined) setRevealUses(savedProgress.revealUses);
        } else {
             initializeBoard();
             // Reset skill uses for new game
             setScanUses(3);
             setRevealUses(1);
        }
    }, [difficulty, levelId, initializeBoard]);

    // Replay Generation
    const handleGenerateReplay = async () => {
        if (isGeneratingReplay || !settings.generateReplay) return;
        setIsGeneratingReplay(true);
        const isDark = document.documentElement.classList.contains('dark');

        try {
            const url = await generateReplayVideo(
                initialBoardRef.current,
                moveLog.current,
                difficulty,
                levelId,
                isDark,
                timer
            );
            setReplayUrl(url);
        } catch (e) {
            console.error(e);
        } finally {
            setIsGeneratingReplay(false);
        }
    };

    return (
        <div className="flex flex-col h-full w-full max-w-lg mx-auto relative">
             {/* Header */}
             <div className="flex items-center justify-between px-6 pt-4 pb-2 z-30 shrink-0">
                  <button onClick={() => { sounds.playClick(); onBack(); }} className="p-2 rounded-full hover:bg-white/20 active:scale-95 transition -ml-2 text-t-icon">
                      <Icons.Back className="w-6 h-6" />
                  </button>

                  {/* Center Info - Absolute to be centered relative to container */}
                  <div className="absolute left-0 right-0 pointer-events-none flex flex-col items-center justify-center">
                      {settings.showTimer ? (
                          <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                      ) : (
                          <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                      )}
                      <span className="text-[10px] font-bold text-stone-500 dark:text-stone-400 uppercase tracking-widest mt-0.5">
                        {difficulty} {settings.showTimer && `• ${levelId}`}
                      </span>
                  </div>

                  <div className="flex items-center gap-3">
                       <div className="flex items-center gap-1 bg-t-surface px-2.5 py-1.5 rounded-full shadow-sm">
                            <AnimatedNumber value={currentPoints} className="text-sm font-bold text-t-primary tabular-nums" />
                            <Icons.Diamond className="w-3.5 h-3.5 text-blue-500 fill-current" />
                       </div>
                       <button onClick={() => { sounds.playClick(); onSettingsOpen(); }} className="p-2 rounded-full hover:bg-white/20 active:scale-95 transition -mr-2 text-t-icon">
                           <Icons.Settings className="w-6 h-6" />
                       </button>
                  </div>
             </div>

             {/* Grid Area */}
             <div className="flex-1 flex flex-col items-center justify-center w-full relative">
                  <SudokuGrid 
                      board={board}
                      selectedCell={selectedCell}
                      activeNumber={activeNumber}
                      conflicts={conflicts}
                      revealingCell={revealingCell}
                      animatingCell={animatingCell}
                      isScanning={isScanning}
                      animatingSections={animatingSections}
                      settings={settings}
                      numberColor={numberColor}
                      onCellClick={(e, r, c) => handleCellClick(r, c, false, isCompleted)}
                  />
             </div>

             {/* Controls Area */}
             <div className="w-full px-6 pb-safe-bottom pt-2 flex flex-col gap-4 shrink-0 z-30 bg-t-bg transition-colors duration-300">
                  <GameControls 
                      canUndo={history.length > 0}
                      canErase={!!selectedCell && !board[selectedCell[0]][selectedCell[1]].isFixed}
                      isPencilMode={isPencilMode}
                      onUndo={(e) => { e.stopPropagation(); handleUndo(false, isCompleted); }}
                      onErase={(e) => { e.stopPropagation(); handleErase(false, isCompleted); }}
                      onTogglePencil={(e) => { 
                          e.stopPropagation(); 
                          sounds.playClick();
                          setIsPencilMode(!isPencilMode); 
                      }}
                      purchasedSkills={purchasedSkills}
                      isAutoAvailable={isAutoAvailable}
                      scanUses={scanUses}
                      isScanning={isScanning}
                      scanCooldown={scanCooldown}
                      revealUses={revealUses}
                      revealingCell={revealingCell}
                      onAutoFill={(e) => { e.stopPropagation(); handleAutoFill(purchasedSkills); }}
                      onScan={(e) => { e.stopPropagation(); handleScan(false, isCompleted); }}
                      onReveal={(e) => { e.stopPropagation(); handleReveal(false, isCompleted); }}
                      timer={timer}
                  />

                  <NumberPad 
                      activeNumber={activeNumber}
                      numberCounts={numberCounts}
                      isPencilMode={isPencilMode}
                      numberColor={numberColor}
                      onNumberClick={(e, num) => { e.stopPropagation(); handleNumberInput(num, false, isCompleted); }}
                  />
                  <div className="h-2" /> {/* Spacer */}
             </div>

             {/* Win Modal */}
             {showWinModal && (
                 <WinModal 
                     difficulty={difficulty}
                     levelId={levelId}
                     timer={timer}
                     points={pointsEarned}
                     isGeneratingReplay={isGeneratingReplay}
                     replayUrl={replayUrl}
                     showReplay={showReplay}
                     generateReplayEnabled={settings.generateReplay}
                     onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
                     onShareReplay={async () => {
                         if (replayUrl) {
                             // Web Share API
                             try {
                                 const blob = await fetch(replayUrl).then(r => r.blob());
                                 const file = new File([blob], `Oku_Sudoku_${difficulty}_${levelId}.mp4`, { type: blob.type });
                                 if (navigator.share && navigator.canShare({ files: [file] })) {
                                     await navigator.share({
                                         files: [file],
                                         title: 'Oku: Sudoku Replay',
                                         text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
                                     });
                                 } else {
                                     // Fallback: Download
                                     const a = document.createElement('a');
                                     a.href = replayUrl;
                                     a.download = `Oku_Sudoku_${difficulty}_${levelId}.mp4`;
                                     document.body.appendChild(a);
                                     a.click();
                                     document.body.removeChild(a);
                                 }
                             } catch (err) {
                                 console.error("Share failed", err);
                             }
                         }
                     }}
                     onCloseReplay={() => setShowReplay(false)}
                     onGenerateReplay={handleGenerateReplay}
                     onBack={(e) => { e.stopPropagation(); onBack(); }}
                     onReturnToMenu={(e) => { e.stopPropagation(); onReturnToMenu(); }}
                 />
             )}
        </div>
    );
};

