.dark .btn-alive-gradient {
  background-color: #1c1917; 
  --alive-blob-1: rgba(120, 113, 108, 0.6); 
  --alive-blob-2: rgba(87, 83, 78, 0.4); 
}

.btn-alive-gradient::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 150%;
  height: 150%;
  background: radial-gradient(circle, var(--alive-blob-1) 0%, transparent 65%);
  transform: translate(-50%, -50%);
  animation: organic-1 4s infinite ease-in-out;
  z-index: 0;
  border-radius: 50%;
}

.btn-alive-gradient::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 120%;
  height: 120%;
  background: radial-gradient(circle, var(--alive-blob-2) 0%, transparent 60%);
  transform: translate(-50%, -50%);
  animation: organic-2 5.5s infinite ease-in-out; 
  z-index: 0;
  border-radius: 50%;
