    onWatchAd: () => void;
    onBuyOffer: (offer: DiamondOffer) => void;
    onEarnPoints: (amount: number) => void;
    starterPackPurchased: boolean;
}

export const DiamondShopScreen: React.FC<DiamondShopScreenProps> = ({
    points,
