  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Track actual dark mode state for JS logic
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Initialize Native Storage, Orientation, IAP, Ads
  useEffect(() => {
    const initStorage = async () => {
        // Initialize native storage
        await Storage.initializeNative();

        // Get updated data
        const data = Storage.getStoredData();

        setPoints(data.points);
        setSettings(data.settings);
        setPurchasedBackgrounds(data.purchasedBackgrounds);
        setPurchasedNumberColors(data.purchasedNumberColors);
        setPurchasedSoundPacks(data.purchasedSoundPacks || ['snd-zen']);
        setSelectedSoundPackId(data.selectedSoundPack || 'snd-zen');
        setPurchasedSkills(data.purchasedSkills);
        setEnabledSkills(data.enabledSkills || [...data.purchasedSkills]);
        setStarterPackPurchased(data.starterPackPurchased || false);
        setUnlockedPacks2(data.unlockedPack2 || []);
        setUnlockedPacks3(data.unlockedPack3 || []);
        setNextBonusClaimTime(data.nextBonusClaimTime || 0);

        const isDark = data.settings.appearance === 'dark' || (data.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
        setIsDarkMode(isDark);
        if (isDark) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    };
    initStorage();

    // Init IAP
    IAP.initialize();

    // Init Ads
    Ads.initialize();

    // Lock Orientation to Portrait
    const lockOrientation = async () => {
        try {
            // Native Lock (Capacitor)
            await ScreenOrientation.lock({ orientation: 'portrait' });
        } catch (e) {
            console.log("Native lock failed or not supported, trying web API");
            // Web API Fallback
            try {
                if (window.screen && window.screen.orientation && typeof (window.screen.orientation as any).lock === 'function') {
                    await (window.screen.orientation as any).lock('portrait');
                }
            } catch (err) {
                // Ignore errors (e.g. desktop browser doesn't support locking)
            }
        }
    };

    lockOrientation();

    // Re-lock on visibility change (sometimes needed on Android resume)
    const handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            lockOrientation();
        }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
        document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
          setIsDarkMode(isDark);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#000000');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const handleToggleDifficultyVisibility = (diff: Difficulty) => {
      sounds.playTap();
      const currentHidden = settings.hiddenDifficulties || [];
      let newHidden: Difficulty[];

      if (currentHidden.includes(diff)) {
          newHidden = currentHidden.filter(d => d !== diff);
      } else {
          // Prevent hiding the last visible difficulty
          const allDiffs = Object.values(Difficulty);
          if (allDiffs.length - currentHidden.length <= 1) {
             return; 
          }
          newHidden = [...currentHidden, diff];
      }

      const newSettings = { ...settings, hiddenDifficulties: newHidden };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = async () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This will clear data from Local Storage and Cloud Backup.")) {
          await Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = (e: React.MouseEvent) => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();

    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + 1);
    nextDate.setHours(0, 0, 0, 0);
    const nextTime = nextDate.getTime();

    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      if (type !== 'sound') {
          sounds.playPop();
      }
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = async () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        sounds.playClick();
        setIsWatchingAd(true); // Show spinner

        // Show Ad (Web uses mock, Native uses AdMob)
        const success = await Ads.showRewardVideo(() => {
            handleAdReward();
        });

        // If native ad failed to show (not loaded), or web mock finished
        // We hide the spinner. If native ad is showing, spinner is covered anyway.
        // It's safe to clear this now as the ad view is top-level.
        setIsWatchingAd(false);

        if (!success) {
            // Can add a toast here if ad fails to load
            console.log("Ad not ready or failed to show");
        }
  };

  const handleAdReward = () => {
      handleEarnPoints(25);
      sounds.playWin();
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;

      handleEarnPoints(offer.diamonds);

      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseSkill('skill-scan', 0);
          Storage.purchaseSoundPack('snd-piano', 0);
      } else if (offer.type === 'support') {
          Storage.unlockPepino();
      }

      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  let activeBackgroundClass = "bg-paper dark:bg-black"; 

  if (selectedBackgroundId && !isDarkMode) {
      const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
      if (bg) {
          activeBackgroundClass = bg.class;
      }
  } else if (isDarkMode) {
      activeBackgroundClass = "bg-black";
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacityValue = 0;
  const baseOverlayOpacity = isDarkMode ? 0.5 : 0;

  if (isGradient) {
      if (screen === 'game') {
          overlayOpacityValue = baseOverlayOpacity * 1.6;
      } else {
          overlayOpacityValue = baseOverlayOpacity;
      }
  } else if (screen === 'game') {
      overlayOpacityValue = baseOverlayOpacity * 0.6;
  }

  const variants: Variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-100%' : 0),
      opacity: 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-100%' : '100%',
      opacity: 0,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    })
  };

  return (
      <>
          {/* Main App Wrapper: Fixed, Full Viewport, No Overflow */}
          <div className="fixed inset-0 z-0 w-full h-full overflow-hidden select-none touch-none">

              {/* Force Landscape Blocker */}
              <LandscapeBlocker />

              {/* Background Layer (Persistent) */}
              <div 
                className={`absolute inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
                style={{ width: '100%', height: '100%' }}
              />
              <div 
                className="absolute inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
                style={{ opacity: overlayOpacityValue }} 
              />

              {/* Diamond Shop Background (Behind Safe Area Wrapper) */}
              {screen === 'diamondShop' && <DiamondBackground />}

              {/* Content Wrapper with Safe Areas */}
              <div 
                 className="relative z-10 w-full h-full flex flex-col pt-safe pb-safe"
              >
                <div className="flex-1 relative w-full h-full overflow-hidden">
                    <AnimatePresence custom={direction} initial={false}>
                        <motion.div
                            key={screen}
                            custom={direction}
                            variants={variants}
                            initial="initial"
                            animate="animate"
                            exit="exit"
                            className="absolute inset-0 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden bg-transparent"
                            style={{ pointerEvents: 'auto' }}
                        >
                            {screen === 'splash' && <SplashScreen />}

                            {screen === 'difficulty' && (
                                <DifficultyScreen 
                                    points={points}
                                    onDifficultySelect={handleDifficultySelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onOpenStore={() => navigate('store', 'forward')}
                                    onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                                    onClaimBonus={handleClaimBonus}
                                    onOpenStats={() => navigate('stats', 'forward')}
                                    nextBonusClaimTime={nextBonusClaimTime}
                                    hiddenDifficulties={settings.hiddenDifficulties}
                                />
                            )}

                            {screen === 'diamondShop' && (
                                <DiamondShopScreen 
                                    points={points}
                                    onBack={handleDiamondShopBack}
                                    onWatchAd={handleWatchAd}
                                    onBuyOffer={handleBuyOffer}
                                    onEarnPoints={handleEarnPoints}
                                    starterPackPurchased={starterPackPurchased}
                                />
                            )}

                            {screen === 'stats' && (
                                <StatsScreen 
                                    onBack={handleStatsBack}
                                    onEarnPoints={handleEarnPoints}
                                    points={points}
                                />
                            )}

                            {screen === 'levels' && selectedDifficulty && (
                                <LevelsScreen 
                                    difficulty={selectedDifficulty}
                                    points={points}
                                    unlockedPacks2={unlockedPacks2}
                                    unlockedPacks3={unlockedPacks3}
                                    onBack={handleLevelBack}
                                    onLevelSelect={handleLevelSelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onUnlockPack2={handleUnlockPack2}
                                    onUnlockPack3={handleUnlockPack3}
                                />
                            )}

                            {screen === 'store' && (
                                <StoreScreen 
                                    points={points}
                                    onBack={handleStoreBack}
                                    purchasedSkills={purchasedSkills}
                                    enabledSkills={enabledSkills}
                                    purchasedBackgrounds={purchasedBackgrounds}
                                    purchasedNumberColors={purchasedNumberColors}
                                    purchasedSoundPacks={purchasedSoundPacks}
                                    selectedBackgroundId={selectedBackgroundId}
                                    selectedNumberColorId={selectedNumberColorId}
                                    selectedSoundPackId={selectedSoundPackId}
                                    onPurchase={initiatePurchase}
                                    onSelectBackground={handleSelectBackground}
                                    onSelectNumberColor={handleSelectNumberColor}
                                    onSelectSoundPack={handleSelectSoundPack}
                                    onToggleSkill={handleToggleSkill}
                                />
                            )}

                            {screen === 'game' && selectedDifficulty && selectedLevel && (
                                <SudokuGame
                                    difficulty={selectedDifficulty}
                                    levelId={selectedLevel}
                                    onBack={handleGameBack}
                                    onReturnToMenu={handleReturnToMenu}
                                    onComplete={() => {
                                        setPoints(Storage.getPoints());
                                    }}
                                    onSettingsOpen={() => setShowSettings(true)}
                                    settings={settings}
                                    onEarnPoints={handleEarnPoints}
                                    currentPoints={points}
                                    isSettingsOpen={showSettings}
                                    backgroundClass={activeBackgroundClass}
                                    numberColor={numberColorClass}
                                    purchasedSkills={enabledSkills}
                                />
                            )}
                        </motion.div>
                    </AnimatePresence>
                </div>

                {/* Modals & Overlays */}
                {showSettings && (
                    <SettingsModal 
                        settings={settings} 
                        onToggle={toggleSetting} 
                        onToggleDifficulty={handleToggleDifficultyVisibility}
                        onSetAppearance={setAppearance}
                        onReset={resetProgress}
                        onClose={() => setShowSettings(false)} 
                    />
                )}
                {replayLevelId !== null && selectedDifficulty && (
                    <ReplayModal 
                        levelId={replayLevelId}
                        onConfirm={confirmReplay}
                        onCancel={() => setReplayLevelId(null)}
                    />
                )}
                {purchaseCandidate && (
                    <PurchaseModal 
                        item={purchaseCandidate} 
                        onConfirm={confirmPurchase} 
                        onCancel={() => setPurchaseCandidate(null)} 
                    />
                )}
                {paymentOffer && (
                    <PaymentModal
                        offer={paymentOffer}
                        onComplete={finalizeRealMoneyPurchase}
                        onCancel={() => setPaymentOffer(null)}
                    />
                )}
                {showNotEnoughPoints && (
                    <NotEnoughPointsModal 
                        onClose={() => setShowNotEnoughPoints(false)} 
                        onGetMore={handleNavigateToShop} 
                        onGoPlay={handleGoPlay} 
                    />
                )}
                {isWatchingAd && (
                    <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-md flex items-center justify-center animate-fade-in">
                        <div className="bg-t-surface p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 animate-pop">
                            <div className="w-10 h-10 border-4 border-stone-200 border-t-blue-500 rounded-full animate-spin"></div>
                            <p className="font-bold text-t-primary">Loading Reward...</p>
                        </div>
                    </div>
                )}
              </div>
          </div>
      </>
  );
}

import { AdMob, RewardAdOptions, AdLoadInfo, RewardAdPluginEvents, AdMobRewardItem } from '@capacitor-community/admob';
import { Capacitor } from '@capacitor/core';

export const AD_IDS = {
    DIAMOND_REWARD: 'ca-app-pub-1693095758192325/2084679142',
    SCAN_REFILL: 'ca-app-pub-1693095758192325/9122706690'
};

class AdMobService {
    private isReady = false;
    private currentAdId: string | null = null;
    private onRewardCallback: (() => void) | null = null;
    private isInitializing = false;

    async initialize() {
        if (!Capacitor.isNativePlatform() || this.isInitializing) return;
        this.isInitializing = true;

        try {
            await AdMob.initialize({
                requestTrackingAuthorization: true,
                initializeForTesting: false, 
            });

            // Listeners
            AdMob.addListener(RewardAdPluginEvents.Loaded, (info: AdLoadInfo) => {
                this.isReady = true;
                console.log('AdMob: Reward Video Loaded', info.adUnitId);
            });

            AdMob.addListener(RewardAdPluginEvents.Dismissed, () => {
                this.isReady = false;
                // Preload the last used ID again for convenience
                if (this.currentAdId) {
                    this.prepare(this.currentAdId);
                }
            });

            AdMob.addListener(RewardAdPluginEvents.Rewarded, (reward: AdMobRewardItem) => {
                console.log('AdMob: User Rewarded', reward);
                if (this.onRewardCallback) {
                    this.onRewardCallback();
                    this.onRewardCallback = null;
                }
            });

            AdMob.addListener(RewardAdPluginEvents.FailedToLoad, (error) => {
                 console.error('AdMob: Failed to load', error);
                 this.isReady = false;
            });

            // Initial Load (Default to Diamond Ad)
            await this.prepare(AD_IDS.DIAMOND_REWARD);

        } catch (e) {
            console.error('AdMob Init Error', e);
        }
    }

    async prepare(adUnitId: string) {
        if (!Capacitor.isNativePlatform()) return;

        this.currentAdId = adUnitId;
        try {
            await AdMob.prepareRewardVideoAd({
                adId: adUnitId
            });
        } catch (e) {
            console.error('AdMob Prepare Error', e);
        }
    }

    async showRewardVideo(adUnitId: string, onReward: () => void): Promise<boolean> {
        // Mock for Web / Development
        if (!Capacitor.isNativePlatform()) {
            console.log(`AdMob: Web Mock - Showing Ad [${adUnitId}] (2s delay)`);
            return new Promise((resolve) => {
                setTimeout(() => {
                    console.log('AdMob: Web Mock - Rewarded');
                    onReward();
                    resolve(true);
                }, 2000);
            });
        }

        // If we want to show a DIFFERENT ad than what is ready, or if nothing is ready
        if (this.currentAdId !== adUnitId || !this.isReady) {
            console.log('AdMob: Ad not ready or ID mismatch, attempting load...');
            this.isReady = false; // Force status reset
            await this.prepare(adUnitId);

            // Wait a moment for load? (Native logic might vary, usually prepare awaits until loaded or failed)
            // Ideally prepareRewardVideoAd promise resolves when loaded.
        }

        if (!this.isReady) return false;

        this.onRewardCallback = onReward;

        try {
            await AdMob.showRewardVideoAd();
            return true;
        } catch (e) {
            console.error('AdMob Show Error', e);
            return false;
        }
    }
}

export const Ads = new AdMobService();

import React, { useState, useEffect } from 'react';
import { Difficulty, AppSettings, DiamondOffer } from './types';
import { SudokuGame } from './components/SudokuGame';
import { Storage } from './utils/storage';
import { sounds } from './utils/sound';
import { getPackCost, NUMBER_COLORS, ALL_BACKGROUNDS } from './utils/constants';
import { motion, AnimatePresence, Variants } from 'framer-motion';
import { ScreenOrientation } from '@capacitor/screen-orientation';
import { IAP } from './utils/iap'; 
import { Ads, AD_IDS } from './utils/ads'; // Import AD_IDS

// UI Components
import { PurchaseModal, ReplayModal, NotEnoughPointsModal, SettingsModal, PaymentModal } from './components/ui/Modals';
import { LandscapeBlocker } from './components/ui/LandscapeBlocker';

// Screens
import { SplashScreen } from './components/screens/SplashScreen';
import { DifficultyScreen } from './components/screens/DifficultyScreen';
import { LevelsScreen } from './components/screens/LevelsScreen';
import { StoreScreen } from './components/screens/StoreScreen';
import { DiamondShopScreen } from './components/screens/DiamondShopScreen';
import { StatsScreen } from './components/screens/StatsScreen';

type Screen = 'splash' | 'difficulty' | 'levels' | 'game' | 'settings' | 'store' | 'diamondShop' | 'stats';

// Optimized Diamond Background Component (CSS-based)
const DiamondBackground = () => (
  <div className="fixed inset-0 pointer-events-none z-0 bg-diamond-pattern" />
);

export function App() {
  const [screen, setScreen] = useState<Screen>('splash');
  const [direction, setDirection] = useState<number>(0);
  const [selectedDifficulty, setSelectedDifficulty] = useState<Difficulty | null>(null);
  const [selectedLevel, setSelectedLevel] = useState<number | null>(null);
  const [settings, setSettings] = useState<AppSettings>(Storage.getSettings());
  const [points, setPoints] = useState<number>(Storage.getPoints());

  const [purchasedBackgrounds, setPurchasedBackgrounds] = useState<string[]>(Storage.getPurchasedBackgrounds());
  const [selectedBackgroundId, setSelectedBackgroundId] = useState<string | null>(Storage.getSelectedBackground());

  const [purchasedNumberColors, setPurchasedNumberColors] = useState<string[]>(Storage.getPurchasedNumberColors());
  const [selectedNumberColorId, setSelectedNumberColorId] = useState<string>(Storage.getSelectedNumberColor());

  const [purchasedSoundPacks, setPurchasedSoundPacks] = useState<string[]>(Storage.getPurchasedSoundPacks());
  const [selectedSoundPackId, setSelectedSoundPackId] = useState<string>(Storage.getSelectedSoundPack());

  const [purchasedSkills, setPurchasedSkills] = useState<string[]>(Storage.getPurchasedSkills());
  const [enabledSkills, setEnabledSkills] = useState<string[]>(Storage.getEnabledSkills());
  const [starterPackPurchased, setStarterPackPurchased] = useState<boolean>(Storage.isStarterPackPurchased());

  // Unlocked Packs State - For Immediate UI Reactivity
  const [unlockedPacks2, setUnlockedPacks2] = useState<string[]>(Storage.getUnlockedPacks2());
  const [unlockedPacks3, setUnlockedPacks3] = useState<string[]>(Storage.getUnlockedPacks3());

  const [showSettings, setShowSettings] = useState(false);
  const [replayLevelId, setReplayLevelId] = useState<number | null>(null);

  const [purchaseCandidate, setPurchaseCandidate] = useState<{id: string, name: string, cost: number, type: 'bg' | 'num' | 'skill' | 'sound', description?: string} | null>(null);
  const [paymentOffer, setPaymentOffer] = useState<DiamondOffer | null>(null);

  const [showNotEnoughPoints, setShowNotEnoughPoints] = useState(false);
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  const [nextBonusClaimTime, setNextBonusClaimTime] = useState(Storage.getNextBonusClaimTime());

  // Track actual dark mode state for JS logic
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Initialize Native Storage, Orientation, IAP, Ads
  useEffect(() => {
    const initStorage = async () => {
        // Initialize native storage
        await Storage.initializeNative();

        // Get updated data
        const data = Storage.getStoredData();

        setPoints(data.points);
        setSettings(data.settings);
        setPurchasedBackgrounds(data.purchasedBackgrounds);
        setPurchasedNumberColors(data.purchasedNumberColors);
        setPurchasedSoundPacks(data.purchasedSoundPacks || ['snd-zen']);
        setSelectedSoundPackId(data.selectedSoundPack || 'snd-zen');
        setPurchasedSkills(data.purchasedSkills);
        setEnabledSkills(data.enabledSkills || [...data.purchasedSkills]);
        setStarterPackPurchased(data.starterPackPurchased || false);
        setUnlockedPacks2(data.unlockedPack2 || []);
        setUnlockedPacks3(data.unlockedPack3 || []);
        setNextBonusClaimTime(data.nextBonusClaimTime || 0);

        const isDark = data.settings.appearance === 'dark' || (data.settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
        setIsDarkMode(isDark);
        if (isDark) document.documentElement.classList.add('dark');
        else document.documentElement.classList.remove('dark');
    };
    initStorage();

    // Init IAP
    IAP.initialize();

    // Init Ads
    Ads.initialize();

    // Lock Orientation to Portrait
    const lockOrientation = async () => {
        try {
            // Native Lock (Capacitor)
            await ScreenOrientation.lock({ orientation: 'portrait' });
        } catch (e) {
            console.log("Native lock failed or not supported, trying web API");
            // Web API Fallback
            try {
                if (window.screen && window.screen.orientation && typeof (window.screen.orientation as any).lock === 'function') {
                    await (window.screen.orientation as any).lock('portrait');
                }
            } catch (err) {
                // Ignore errors (e.g. desktop browser doesn't support locking)
            }
        }
    };

    lockOrientation();

    // Re-lock on visibility change (sometimes needed on Android resume)
    const handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            lockOrientation();
        }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);

    return () => {
        document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, []);

  // Theme Detection
  useEffect(() => {
      const applyTheme = () => {
          const isDark = settings.appearance === 'dark' || (settings.appearance === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
          setIsDarkMode(isDark);

          if (isDark) {
              document.documentElement.classList.add('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#000000');
          } else {
              document.documentElement.classList.remove('dark');
              document.querySelector('meta[name="theme-color"]')?.setAttribute('content', '#fafaf9');
          }
      };
      applyTheme();
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handler = () => {
          if (settings.appearance === 'system') applyTheme();
      };
      mediaQuery.addEventListener('change', handler);
      return () => mediaQuery.removeEventListener('change', handler);
  }, [settings.appearance]);

  useEffect(() => { 
      sounds.setEnabled(settings.sound); 
      sounds.setVibrationEnabled(settings.vibration);
      sounds.setProfile(selectedSoundPackId);
  }, [settings.sound, settings.vibration, selectedSoundPackId]);

  useEffect(() => {
    const timer = setTimeout(() => {
        setDirection(1);
        setScreen('difficulty');
    }, 1500);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
     setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
     setSelectedBackgroundId(Storage.getSelectedBackground());
     setPurchasedNumberColors(Storage.getPurchasedNumberColors());
     setSelectedNumberColorId(Storage.getSelectedNumberColor());
     setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
     setSelectedSoundPackId(Storage.getSelectedSoundPack());
     setPurchasedSkills(Storage.getPurchasedSkills());
     setEnabledSkills(Storage.getEnabledSkills());
     setStarterPackPurchased(Storage.isStarterPackPurchased());
     setPoints(Storage.getPoints());
     setUnlockedPacks2(Storage.getUnlockedPacks2());
     setUnlockedPacks3(Storage.getUnlockedPacks3());
     setNextBonusClaimTime(Storage.getNextBonusClaimTime());
  }, [screen]);

  const navigate = (nextScreen: Screen, dir: 'forward' | 'back' | 'none' = 'forward') => {
      setDirection(dir === 'forward' ? 1 : dir === 'back' ? -1 : 0);
      setScreen(nextScreen);
      setPoints(Storage.getPoints());
  };

  const handleDifficultySelect = (diff: Difficulty) => {
    sounds.playClick();
    setSelectedDifficulty(diff);
    navigate('levels', 'forward');
  };

  const handleLevelBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleGameBack = () => { sounds.playClick(); navigate('levels', 'back'); };
  const handleReturnToMenu = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStoreBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleDiamondShopBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };
  const handleStatsBack = () => { sounds.playClick(); navigate('difficulty', 'back'); };

  const handleLevelSelect = (levelId: number) => {
    const progress = Storage.getLevelProgress(selectedDifficulty!, levelId);
    if (progress?.status === 'completed') {
        sounds.playClick();
        setReplayLevelId(levelId);
    } else {
        sounds.playLevelEnter();
        setSelectedLevel(levelId);
        navigate('game', 'forward');
    }
  };

  const confirmReplay = () => {
      sounds.playLevelEnter();
      if (selectedDifficulty && replayLevelId) {
          Storage.clearLevelProgress(selectedDifficulty, replayLevelId);
          setReplayLevelId(null);
          setSelectedLevel(replayLevelId);
          navigate('game', 'forward');
      }
  };

  const toggleSetting = (key: keyof AppSettings) => {
    sounds.playClick();
    const newSettings = { ...settings, [key]: !settings[key] };
    setSettings(newSettings);
    Storage.saveSettings(newSettings);
  };

  const handleToggleDifficultyVisibility = (diff: Difficulty) => {
      sounds.playTap();
      const currentHidden = settings.hiddenDifficulties || [];
      let newHidden: Difficulty[];

      if (currentHidden.includes(diff)) {
          newHidden = currentHidden.filter(d => d !== diff);
      } else {
          // Prevent hiding the last visible difficulty
          const allDiffs = Object.values(Difficulty);
          if (allDiffs.length - currentHidden.length <= 1) {
             return; 
          }
          newHidden = [...currentHidden, diff];
      }

      const newSettings = { ...settings, hiddenDifficulties: newHidden };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const setAppearance = (val: 'system' | 'light' | 'dark') => {
      const newSettings = { ...settings, appearance: val };
      setSettings(newSettings);
      Storage.saveSettings(newSettings);
  };

  const resetProgress = async () => {
      sounds.playClick();
      if (confirm("Are you sure you want to reset all progress? This will clear data from Local Storage and Cloud Backup.")) {
          await Storage.resetAllData();
          window.location.reload();
      }
  };

  const handleSelectBackground = (id: string) => {
      sounds.playClick();
      Storage.selectBackground(id);
      setSelectedBackgroundId(id);
  };

  const handleSelectNumberColor = (id: string) => {
      sounds.playClick();
      Storage.selectNumberColor(id);
      setSelectedNumberColorId(id);
  };

  const handleSelectSoundPack = (id: string) => {
    Storage.selectSoundPack(id);
    setSelectedSoundPackId(id);
  };

  const handleToggleSkill = (id: string) => {
    const next = Storage.toggleSkillEnabled(id);
    setEnabledSkills([...next]);
  };

  const handleEarnPoints = (amount: number) => {
    const newTotal = Storage.addPoints(amount);
    setPoints(newTotal);
  };

  const handleClaimBonus = (e: React.MouseEvent) => {
    const now = Date.now();
    if (now < nextBonusClaimTime) return;
    sounds.playWin();

    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + 1);
    nextDate.setHours(0, 0, 0, 0);
    const nextTime = nextDate.getTime();

    Storage.setNextBonusClaimTime(nextTime);
    setNextBonusClaimTime(nextTime);
    handleEarnPoints(10);
  };

  const initiatePurchase = (item: any, type: 'bg' | 'num' | 'skill' | 'sound') => {
      if (type !== 'sound') {
          sounds.playPop();
      }
      setPurchaseCandidate({ ...item, type });
  };

  const confirmPurchase = () => {
      if (!purchaseCandidate) return;
      if (points >= purchaseCandidate.cost) {
          if (purchaseCandidate.type === 'bg') {
             if(Storage.purchaseBackground(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedBackgrounds([...purchasedBackgrounds, purchaseCandidate.id]);
                handleSelectBackground(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'num') {
             if(Storage.purchaseNumberColor(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedNumberColors([...purchasedNumberColors, purchaseCandidate.id]);
                handleSelectNumberColor(purchaseCandidate.id);
             }
          } else if (purchaseCandidate.type === 'skill') {
             if(Storage.purchaseSkill(purchaseCandidate.id, purchaseCandidate.cost)) {
                setPurchasedSkills(Storage.getPurchasedSkills());
                setEnabledSkills(Storage.getEnabledSkills());
             }
          } else if (purchaseCandidate.type === 'sound') {
            if(Storage.purchaseSoundPack(purchaseCandidate.id, purchaseCandidate.cost)) {
               setPurchasedSoundPacks([...purchasedSoundPacks, purchaseCandidate.id]);
               handleSelectSoundPack(purchaseCandidate.id);
            }
          }
          setPoints(Storage.getPoints());
          setPurchaseCandidate(null);
      } else {
          setPurchaseCandidate(null);
          setShowNotEnoughPoints(true);
      }
  };

  const handleWatchAd = async () => {
        setShowNotEnoughPoints(false);
        setPurchaseCandidate(null);
        sounds.playClick();
        setIsWatchingAd(true); // Show spinner

        // Show Ad (DIAMOND REWARD)
        const success = await Ads.showRewardVideo(AD_IDS.DIAMOND_REWARD, () => {
            handleAdReward();
        });

        setIsWatchingAd(false);

        if (!success) {
            console.log("Ad not ready or failed to show");
        }
  };

  const handleAdReward = () => {
      handleEarnPoints(25);
      sounds.playWin();
  };

  const handleNavigateToShop = () => {
      setShowNotEnoughPoints(false);
      navigate('diamondShop', 'forward');
  };

  const handleGoPlay = () => {
      setShowNotEnoughPoints(false);
      setPurchaseCandidate(null);
      if (screen === 'store') {
          navigate('difficulty', 'back');
      }
  };

  const handleBuyOffer = (offer: DiamondOffer) => {
      sounds.playClick();
      if (offer.type === 'starter' && starterPackPurchased) return;
      if (offer.priceLabel === '') return;
      setPaymentOffer(offer);
  };

  const finalizeRealMoneyPurchase = () => {
      if (!paymentOffer) return;
      const offer = paymentOffer;

      handleEarnPoints(offer.diamonds);

      if (offer.type === 'starter') {
          Storage.setStarterPackPurchased();
          setStarterPackPurchased(true);
          Storage.purchaseSkill('skill-auto', 0);
          Storage.purchaseSkill('skill-scan', 0);
          Storage.purchaseSoundPack('snd-piano', 0);
      } else if (offer.type === 'support') {
          Storage.unlockPepino();
      }

      setPurchasedSkills(Storage.getPurchasedSkills());
      setEnabledSkills(Storage.getEnabledSkills());
      setPurchasedNumberColors(Storage.getPurchasedNumberColors());
      setPurchasedBackgrounds(Storage.getPurchasedBackgrounds());
      setPurchasedSoundPacks(Storage.getPurchasedSoundPacks());
      setPaymentOffer(null);
  };

  const handleUnlockPack2 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 2);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack2(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks2(Storage.getUnlockedPacks2());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  const handleUnlockPack3 = () => {
      if (!selectedDifficulty) return;
      const cost = getPackCost(selectedDifficulty, 3);
      if (points >= cost) {
          sounds.playPop();
          if (Storage.unlockPack3(selectedDifficulty, cost)) {
              setPoints(Storage.getPoints());
              setUnlockedPacks3(Storage.getUnlockedPacks3());
              sounds.playWin();
          }
      } else {
          sounds.playClick();
          setShowNotEnoughPoints(true);
      }
  };

  let activeBackgroundClass = "bg-paper dark:bg-black"; 

  if (selectedBackgroundId && !isDarkMode) {
      const bg = ALL_BACKGROUNDS.find(b => b.id === selectedBackgroundId);
      if (bg) {
          activeBackgroundClass = bg.class;
      }
  } else if (isDarkMode) {
      activeBackgroundClass = "bg-black";
  }

  const numberColorClass = NUMBER_COLORS.find(n => n.id === selectedNumberColorId)?.class || 'text-blue-600';

  const isGradient = activeBackgroundClass.includes('bg-gradient');
  let overlayOpacityValue = 0;
  const baseOverlayOpacity = isDarkMode ? 0.5 : 0;

  if (isGradient) {
      if (screen === 'game') {
          overlayOpacityValue = baseOverlayOpacity * 1.6;
      } else {
          overlayOpacityValue = baseOverlayOpacity;
      }
  } else if (screen === 'game') {
      overlayOpacityValue = baseOverlayOpacity * 0.6;
  }

  const variants: Variants = {
    initial: (dir: number) => ({
      x: dir > 0 ? '100%' : (dir < 0 ? '-100%' : 0),
      opacity: 0
    }),
    animate: {
      x: 0,
      opacity: 1,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    },
    exit: (dir: number) => ({
      x: dir > 0 ? '-100%' : '100%',
      opacity: 0,
      transition: { 
          type: "spring", 
          stiffness: 260, 
          damping: 25
      }
    })
  };

  return (
      <>
          {/* Main App Wrapper: Fixed, Full Viewport, No Overflow */}
          <div className="fixed inset-0 z-0 w-full h-full overflow-hidden select-none touch-none">

              {/* Force Landscape Blocker */}
              <LandscapeBlocker />

              {/* Background Layer (Persistent) */}
              <div 
                className={`absolute inset-0 z-0 transition-all ease-in-out duration-500 ${activeBackgroundClass}`} 
                style={{ width: '100%', height: '100%' }}
              />
              <div 
                className="absolute inset-0 z-[1] bg-black pointer-events-none transition-opacity duration-500" 
                style={{ opacity: overlayOpacityValue }} 
              />

              {/* Diamond Shop Background (Behind Safe Area Wrapper) */}
              {screen === 'diamondShop' && <DiamondBackground />}

              {/* Content Wrapper with Safe Areas */}
              <div 
                 className="relative z-10 w-full h-full flex flex-col pt-safe pb-safe"
              >
                <div className="flex-1 relative w-full h-full overflow-hidden">
                    <AnimatePresence custom={direction} initial={false}>
                        <motion.div
                            key={screen}
                            custom={direction}
                            variants={variants}
                            initial="initial"
                            animate="animate"
                            exit="exit"
                            className="absolute inset-0 w-full h-full flex flex-col items-center justify-center font-sans text-t-primary overflow-hidden bg-transparent"
                            style={{ pointerEvents: 'auto' }}
                        >
                            {screen === 'splash' && <SplashScreen />}

                            {screen === 'difficulty' && (
                                <DifficultyScreen 
                                    points={points}
                                    onDifficultySelect={handleDifficultySelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onOpenStore={() => navigate('store', 'forward')}
                                    onOpenDiamondShop={() => navigate('diamondShop', 'forward')}
                                    onClaimBonus={handleClaimBonus}
                                    onOpenStats={() => navigate('stats', 'forward')}
                                    nextBonusClaimTime={nextBonusClaimTime}
                                    hiddenDifficulties={settings.hiddenDifficulties}
                                />
                            )}

                            {screen === 'diamondShop' && (
                                <DiamondShopScreen 
                                    points={points}
                                    onBack={handleDiamondShopBack}
                                    onWatchAd={handleWatchAd}
                                    onBuyOffer={handleBuyOffer}
                                    onEarnPoints={handleEarnPoints}
                                    starterPackPurchased={starterPackPurchased}
                                />
                            )}

                            {screen === 'stats' && (
                                <StatsScreen 
                                    onBack={handleStatsBack}
                                    onEarnPoints={handleEarnPoints}
                                    points={points}
                                />
                            )}

                            {screen === 'levels' && selectedDifficulty && (
                                <LevelsScreen 
                                    difficulty={selectedDifficulty}
                                    points={points}
                                    unlockedPacks2={unlockedPacks2}
                                    unlockedPacks3={unlockedPacks3}
                                    onBack={handleLevelBack}
                                    onLevelSelect={handleLevelSelect}
                                    onOpenSettings={() => setShowSettings(true)}
                                    onUnlockPack2={handleUnlockPack2}
                                    onUnlockPack3={handleUnlockPack3}
                                />
                            )}

                            {screen === 'store' && (
                                <StoreScreen 
                                    points={points}
                                    onBack={handleStoreBack}
                                    purchasedSkills={purchasedSkills}
                                    enabledSkills={enabledSkills}
                                    purchasedBackgrounds={purchasedBackgrounds}
                                    purchasedNumberColors={purchasedNumberColors}
                                    purchasedSoundPacks={purchasedSoundPacks}
                                    selectedBackgroundId={selectedBackgroundId}
                                    selectedNumberColorId={selectedNumberColorId}
                                    selectedSoundPackId={selectedSoundPackId}
                                    onPurchase={initiatePurchase}
                                    onSelectBackground={handleSelectBackground}
                                    onSelectNumberColor={handleSelectNumberColor}
                                    onSelectSoundPack={handleSelectSoundPack}
                                    onToggleSkill={handleToggleSkill}
                                />
                            )}

                            {screen === 'game' && selectedDifficulty && selectedLevel && (
                                <SudokuGame
                                    difficulty={selectedDifficulty}
                                    levelId={selectedLevel}
                                    onBack={handleGameBack}
                                    onReturnToMenu={handleReturnToMenu}
                                    onComplete={() => {
                                        setPoints(Storage.getPoints());
                                    }}
                                    onSettingsOpen={() => setShowSettings(true)}
                                    settings={settings}
                                    onEarnPoints={handleEarnPoints}
                                    currentPoints={points}
                                    isSettingsOpen={showSettings}
                                    backgroundClass={activeBackgroundClass}
                                    numberColor={numberColorClass}
                                    purchasedSkills={enabledSkills}
                                />
                            )}
                        </motion.div>
                    </AnimatePresence>
                </div>

                {/* Modals & Overlays */}
                {showSettings && (
                    <SettingsModal 
                        settings={settings} 
                        onToggle={toggleSetting} 
                        onToggleDifficulty={handleToggleDifficultyVisibility}
                        onSetAppearance={setAppearance}
                        onReset={resetProgress}
                        onClose={() => setShowSettings(false)} 
                    />
                )}
                {replayLevelId !== null && selectedDifficulty && (
                    <ReplayModal 
                        levelId={replayLevelId}
                        onConfirm={confirmReplay}
                        onCancel={() => setReplayLevelId(null)}
                    />
                )}
                {purchaseCandidate && (
                    <PurchaseModal 
                        item={purchaseCandidate} 
                        onConfirm={confirmPurchase} 
                        onCancel={() => setPurchaseCandidate(null)} 
                    />
                )}
                {paymentOffer && (
                    <PaymentModal
                        offer={paymentOffer}
                        onComplete={finalizeRealMoneyPurchase}
                        onCancel={() => setPaymentOffer(null)}
                    />
                )}
                {showNotEnoughPoints && (
                    <NotEnoughPointsModal 
                        onClose={() => setShowNotEnoughPoints(false)} 
                        onGetMore={handleNavigateToShop} 
                        onGoPlay={handleGoPlay} 
                    />
                )}
                {isWatchingAd && (
                    <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-md flex items-center justify-center animate-fade-in">
                        <div className="bg-t-surface p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 animate-pop">
                            <div className="w-10 h-10 border-4 border-stone-200 border-t-blue-500 rounded-full animate-spin"></div>
                            <p className="font-bold text-t-primary">Loading Reward...</p>
                        </div>
                    </div>
                )}
              </div>
          </div>
      </>
  );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board, MoveLogEntry } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';
import { Ads, AD_IDS } from '../utils/ads';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  // Game-specific Loading Overlay (for Ad)
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      0
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number, moveLog?: MoveLogEntry[], isPerfect: boolean = false) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          moveLog: moveLog,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses,
      }, isPerfect);
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board, completedMoveLog: MoveLogEntry[], isPerfect: boolean) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          moveLog: completedMoveLog,
          lastPlayed: Date.now(),
          scanUses,
          revealUses,
      }, isPerfect);

      // Grant Pepino Gift on Win
      Storage.grantPepinoGift();

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard, currentMoveLog) => saveProgress(newBoard, undefined, undefined, currentMoveLog),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal,
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r, ml) => saveProgress(b, s, r, ml),
      onSectionComplete: handleSectionComplete,
      timer
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState, progress.moveLog);
          setTimer(progress.timeElapsed);

          // Restore skills
          if (progress.scanUses !== undefined) setScanUses(progress.scanUses);
          else setScanUses(3);

          if (progress.revealUses !== undefined) setRevealUses(progress.revealUses);
          else setRevealUses(1);
      } else {
          initializeBoard();
          setTimer(0);

          // Reset skills
          setScanUses(3);
          setRevealUses(1);
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard, setTimer, setScanUses, setRevealUses]);

  const handleWatchScanAd = async () => {
        setIsWatchingAd(true);
        sounds.playClick();

        // Show Ad (Refill Scans)
        const success = await Ads.showRewardVideo(AD_IDS.SCAN_REFILL, () => {
            setScanUses(3);
            sounds.playWin();
        });

        setIsWatchingAd(false);

        if (!success) {
            console.log("Ad failed to show");
        }
  };

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves, reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `Oku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Oku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  // Determine if erase is possible for the selected cell (value or notes)
  const canErase = !!selectedCell && (() => {
      const [r, c] = selectedCell;
      const cell = board[r][c];
      return !cell.isFixed && (cell.value !== null || cell.notes.length > 0);
  })();

  // Memoize click handlers to avoid passing new functions on every timer tick
  const onCellClickWrapper = useCallback((e: React.MouseEvent, r: number, c: number) => {
      handleCellClick(r, c, isPaused, isCompleted);
  }, [handleCellClick, isPaused, isCompleted]);

  const onNumberClickWrapper = useCallback((e: React.MouseEvent, n: number) => {
      handleNumberInput(n, isPaused, isCompleted);
  }, [handleNumberInput, isPaused, isCompleted]);

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-4 pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-stone-600 dark:text-stone-400 uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <div className="contents">
            <SudokuGrid 
                board={board}
                selectedCell={selectedCell}
                activeNumber={activeNumber}
                conflicts={conflicts}
                revealingCell={revealingCell}
                animatingCell={animatingCell}
                isScanning={isScanning}
                animatingSections={animatingSections}
                settings={settings}
                numberColor={numberColor}
                onCellClick={onCellClickWrapper}
            />
         </div>

         {/* Number Pad - Wider [500px] to match grid */}
         <div className="w-full max-w-[500px] px-2 mt-4 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={onNumberClickWrapper}
             />
         </div>

         {/* Game Controls - Increased spacing (mt-10) */}
         <div className="w-full max-w-md px-6 mt-10 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={canErase}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onWatchScanAd={handleWatchScanAd}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
                 timer={timer}
             />
         </div>

         {/* Deselect Text - Increased spacing (mt-8) */}
         <div className={`mt-8 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-xs font-light text-stone-400 dark:text-stone-500 tracking-wide">Tap here to deselect</span>
         </div>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isWatchingAd && (
          <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-md flex items-center justify-center animate-fade-in">
              <div className="bg-t-surface p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 animate-pop">
                  <div className="w-10 h-10 border-4 border-stone-200 border-t-blue-500 rounded-full animate-spin"></div>
                  <p className="font-bold text-t-primary">Loading Reward...</p>
              </div>
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import React from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';

interface GameControlsProps {
    canUndo: boolean;
    canErase: boolean;
    isPencilMode: boolean;
    onUndo: (e: React.MouseEvent) => void;
    onErase: (e: React.MouseEvent) => void;
    onTogglePencil: (e: React.MouseEvent) => void;
    purchasedSkills: string[];
    // Skill specific props
    isAutoAvailable: boolean;
    scanUses: number;
    isScanning: boolean;
    scanCooldown: boolean;
    revealUses: number;
    revealingCell: {r: number, c: number} | null;
    onAutoFill: (e: React.MouseEvent) => void;
    onScan: (e: React.MouseEvent) => void;
    onWatchScanAd: (e: React.MouseEvent) => void;
    onReveal: (e: React.MouseEvent) => void;
    timer: number;
}

export const GameControls: React.FC<GameControlsProps> = ({
    canUndo,
    canErase,
    isPencilMode,
    onUndo,
    onErase,
    onTogglePencil,
    purchasedSkills,
    isAutoAvailable,
    scanUses,
    isScanning,
    scanCooldown,
    revealUses,
    revealingCell,
    onAutoFill,
    onScan,
    onWatchScanAd,
    onReveal,
    timer
}) => {
    // Helper for common enabled/disabled styles
    const getBaseButtonStyle = (isEnabled: boolean) => 
        isEnabled 
            ? 'text-stone-900 dark:text-stone-100 cursor-pointer hover:brightness-95 active:scale-95' 
            : 'text-stone-300 dark:text-stone-600 cursor-not-allowed';

    // Removed borders from base container styles
    const getBaseContainerStyle = (isEnabled: boolean) => 
        isEnabled
            ? 'bg-white dark:bg-stone-800'
            : 'bg-t-surface-sec dark:bg-stone-800/50';

    const revealTimeLeft = Math.max(0, 60 - timer);
    const isRevealLocked = revealTimeLeft > 0;

    return (
        <div className="flex justify-between w-full relative">
            {/* Reveal Skill Button */}
            {purchasedSkills.includes('skill-reveal') && (
                    <button 
                        onClick={(e) => { e.stopPropagation(); onReveal(e); }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(revealUses > 0 && !revealingCell && !isRevealLocked)}`}
                        disabled={revealUses <= 0 || !!revealingCell || isRevealLocked}
                    >
                    {/* Removed border class */}
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(revealUses > 0 && !isRevealLocked)}`}>
                        {isRevealLocked ? (
                            <div className="w-5 h-5 flex items-center justify-center">
                                <span className="text-[10px] font-bold text-stone-400 font-mono leading-none">{revealTimeLeft}s</span>
                            </div>
                        ) : (
                            <Icons.Reveal className={`w-5 h-5 ${revealUses > 0 ? 'text-purple-600 dark:text-purple-400' : 'text-stone-300 dark:text-stone-600'}`} />
                        )}

                        {/* Larger Badge for Reveal - Moved to -top-4 -right-4 */}
                        <div className={`absolute -top-4 -right-4 w-7 h-7 rounded-full flex items-center justify-center text-base font-bold leading-none shadow-sm z-10 ${revealUses > 0 && !isRevealLocked ? 'bg-blue-600 text-white' : 'bg-stone-300 text-white dark:bg-stone-600'}`}>
                                {revealUses > 0 ? revealUses : '+'}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Reveal</span>
                </button>
            )}

            {/* Scan Skill Button */}
            {purchasedSkills.includes('skill-scan') && (
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            if (scanUses > 0) onScan(e);
                            else onWatchScanAd(e);
                        }} 
                        // Enabled if uses > 0 OR if we can watch an ad (uses == 0)
                        // Disabled only if active cooldown/scanning
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(!scanCooldown && !isScanning)}`}
                        disabled={scanCooldown || isScanning}
                    >
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(!scanCooldown && !isScanning)}`}>
                        <Icons.Scan className={`w-5 h-5 ${scanUses > 0 && !scanCooldown && !isScanning ? 'text-red-600 dark:text-red-400' : (scanUses === 0 ? 'text-blue-500' : 'text-stone-300 dark:text-stone-600')}`} />

                        {/* Badge for Scan */}
                        <div className={`absolute -top-4 -right-4 w-7 h-7 rounded-full flex items-center justify-center text-base font-bold leading-none shadow-sm z-10 ${scanUses > 0 ? 'bg-blue-600 text-white' : 'bg-blue-600 text-white'}`}>
                            {scanUses > 0 ? scanUses : <span className="text-[10px]">Ad</span>}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Scan</span>
                </button>
            )}

            {/* Auto Skill Button */}
            {purchasedSkills.includes('skill-auto') && (
                <button 
                    onClick={(e) => { e.stopPropagation(); onAutoFill(e); }} 
                    className={`flex flex-col items-center gap-1 transition relative active:scale-95 ${isAutoAvailable ? 'cursor-pointer text-amber-700 dark:text-amber-400' : 'cursor-not-allowed text-stone-300 dark:text-stone-600'}`}
                    disabled={!isAutoAvailable}
                >
                    {/* Removed borders and rings */}
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 ${
                        isAutoAvailable 
                        ? 'bg-amber-100 dark:bg-amber-900/30' 
                        : 'bg-t-surface-sec dark:bg-stone-800/50'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
                    </div>
                    <span className="text-sm font-medium">Auto</span>
                </button>
            )}

            {/* UNDO BUTTON */}
            <button 
                onClick={onUndo} 
                disabled={!canUndo}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canUndo)}`}
            >
                <div className={`p-3 rounded-full shadow-sm transition-colors ${getBaseContainerStyle(canUndo)}`}>
                    <Icons.Undo className={`w-5 h-5 ${canUndo ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Undo</span>
            </button>

            {/* PENCIL BUTTON */}
            <button 
                onClick={onTogglePencil} 
                className={`flex flex-col items-center gap-1 active:scale-95 transition cursor-pointer hover:brightness-95 ${isPencilMode ? 'text-blue-700 dark:text-blue-300' : 'text-stone-900 dark:text-stone-100'}`}
            >
                {/* Removed borders */}
                <div className={`p-3 rounded-full shadow-sm transition-colors ${
                    isPencilMode 
                    ? 'bg-blue-100 dark:bg-blue-900/40' 
                    : 'bg-white dark:bg-stone-800'
                }`}>
                    <Icons.Pencil className={`w-5 h-5 ${isPencilMode ? 'text-blue-600 dark:text-blue-400' : 'text-stone-700 dark:text-stone-300'}`} />
                </div>
                <span className="text-sm font-medium">Pencil</span>
            </button>

            {/* ERASE BUTTON */}
            <button 
                onClick={onErase} 
                disabled={!canErase}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canErase)}`}
            >
                <div className={`p-3 rounded-full shadow-sm transition-colors ${getBaseContainerStyle(canErase)}`}>
                    <Icons.Erase className={`w-5 h-5 ${canErase ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Erase</span>
            </button>
        </div>
    );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board, MoveLogEntry } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';
import { Ads, AD_IDS } from '../utils/ads';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  // Game-specific Loading Overlay (for Ad)
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      0
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number, moveLog?: MoveLogEntry[], isPerfect: boolean = false) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          moveLog: moveLog,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses,
      }, isPerfect);
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board, completedMoveLog: MoveLogEntry[], isPerfect: boolean) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          moveLog: completedMoveLog,
          lastPlayed: Date.now(),
          scanUses,
          revealUses,
      }, isPerfect);

      // Grant Pepino Gift on Win
      Storage.grantPepinoGift();

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard, currentMoveLog) => saveProgress(newBoard, undefined, undefined, currentMoveLog),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal,
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r, ml) => saveProgress(b, s, r, ml),
      onSectionComplete: handleSectionComplete,
      timer
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState, progress.moveLog);
          setTimer(progress.timeElapsed);

          // Restore skills
          if (progress.scanUses !== undefined) setScanUses(progress.scanUses);
          else setScanUses(3);

          if (progress.revealUses !== undefined) setRevealUses(progress.revealUses);
          else setRevealUses(1);
      } else {
          initializeBoard();
          setTimer(0);

          // Reset skills
          setScanUses(3);
          setRevealUses(1);
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard, setTimer, setScanUses, setRevealUses]);

  const handleWatchScanAd = async () => {
        setIsWatchingAd(true);
        sounds.playClick();

        // Show Ad (Refill Scans)
        const success = await Ads.showRewardVideo(AD_IDS.SCAN_REFILL, () => {
            // Reward: 1 use
            setScanUses(1);
            sounds.playWin();
        });

        setIsWatchingAd(false);

        if (!success) {
            console.log("Ad failed to show");
        }
  };

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves, reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `Oku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Oku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  // Determine if erase is possible for the selected cell (value or notes)
  const canErase = !!selectedCell && (() => {
      const [r, c] = selectedCell;
      const cell = board[r][c];
      return !cell.isFixed && (cell.value !== null || cell.notes.length > 0);
  })();

  // Memoize click handlers to avoid passing new functions on every timer tick
  const onCellClickWrapper = useCallback((e: React.MouseEvent, r: number, c: number) => {
      handleCellClick(r, c, isPaused, isCompleted);
  }, [handleCellClick, isPaused, isCompleted]);

  const onNumberClickWrapper = useCallback((e: React.MouseEvent, n: number) => {
      handleNumberInput(n, isPaused, isCompleted);
  }, [handleNumberInput, isPaused, isCompleted]);

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-4 pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-stone-600 dark:text-stone-400 uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <div className="contents">
            <SudokuGrid 
                board={board}
                selectedCell={selectedCell}
                activeNumber={activeNumber}
                conflicts={conflicts}
                revealingCell={revealingCell}
                animatingCell={animatingCell}
                isScanning={isScanning}
                animatingSections={animatingSections}
                settings={settings}
                numberColor={numberColor}
                onCellClick={onCellClickWrapper}
            />
         </div>

         {/* Number Pad - Wider [500px] to match grid */}
         <div className="w-full max-w-[500px] px-2 mt-4 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={onNumberClickWrapper}
             />
         </div>

         {/* Game Controls - Increased spacing (mt-10) */}
         <div className="w-full max-w-md px-6 mt-10 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={canErase}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onWatchScanAd={handleWatchScanAd}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
                 timer={timer}
             />
         </div>

         {/* Deselect Text - Increased spacing (mt-8) */}
         <div className={`mt-8 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-xs font-light text-stone-400 dark:text-stone-500 tracking-wide">Tap here to deselect</span>
         </div>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isWatchingAd && (
          <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-md flex items-center justify-center animate-fade-in">
              <div className="bg-t-surface p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 animate-pop">
                  <div className="w-10 h-10 border-4 border-stone-200 border-t-blue-500 rounded-full animate-spin"></div>
                  <p className="font-bold text-t-primary">Loading Reward...</p>
              </div>
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import { AdMob, RewardAdOptions, AdLoadInfo, RewardAdPluginEvents, AdMobRewardItem } from '@capacitor-community/admob';
import { Capacitor } from '@capacitor/core';

export const AD_IDS = {
    DIAMOND_REWARD: 'ca-app-pub-1693095758192325/2084679142',
    SCAN_REFILL: 'ca-app-pub-1693095758192325/9122706690',
    REVEAL_REFILL: 'ca-app-pub-1693095758192325/2850965902'
};

class AdMobService {
    private isReady = false;
    private currentAdId: string | null = null;
    private onRewardCallback: (() => void) | null = null;
    private isInitializing = false;

    async initialize() {
        if (!Capacitor.isNativePlatform() || this.isInitializing) return;
        this.isInitializing = true;

        try {
            await AdMob.initialize({
                requestTrackingAuthorization: true,
                initializeForTesting: false, 
            });

            // Listeners
            AdMob.addListener(RewardAdPluginEvents.Loaded, (info: AdLoadInfo) => {
                this.isReady = true;
                console.log('AdMob: Reward Video Loaded', info.adUnitId);
            });

            AdMob.addListener(RewardAdPluginEvents.Dismissed, () => {
                this.isReady = false;
                // Preload the last used ID again for convenience
                if (this.currentAdId) {
                    this.prepare(this.currentAdId);
                }
            });

            AdMob.addListener(RewardAdPluginEvents.Rewarded, (reward: AdMobRewardItem) => {
                console.log('AdMob: User Rewarded', reward);
                if (this.onRewardCallback) {
                    this.onRewardCallback();
                    this.onRewardCallback = null;
                }
            });

            AdMob.addListener(RewardAdPluginEvents.FailedToLoad, (error) => {
                 console.error('AdMob: Failed to load', error);
                 this.isReady = false;
            });

            // Initial Load (Default to Diamond Ad)
            await this.prepare(AD_IDS.DIAMOND_REWARD);

        } catch (e) {
            console.error('AdMob Init Error', e);
        }
    }

    async prepare(adUnitId: string) {
        if (!Capacitor.isNativePlatform()) return;

        this.currentAdId = adUnitId;
        try {
            await AdMob.prepareRewardVideoAd({
                adId: adUnitId
            });
        } catch (e) {
            console.error('AdMob Prepare Error', e);
        }
    }

    async showRewardVideo(adUnitId: string, onReward: () => void): Promise<boolean> {
        // Mock for Web / Development
        if (!Capacitor.isNativePlatform()) {
            console.log(`AdMob: Web Mock - Showing Ad [${adUnitId}] (2s delay)`);
            return new Promise((resolve) => {
                setTimeout(() => {
                    console.log('AdMob: Web Mock - Rewarded');
                    onReward();
                    resolve(true);
                }, 2000);
            });
        }

        // If we want to show a DIFFERENT ad than what is ready, or if nothing is ready
        if (this.currentAdId !== adUnitId || !this.isReady) {
            console.log('AdMob: Ad not ready or ID mismatch, attempting load...');
            this.isReady = false; // Force status reset
            await this.prepare(adUnitId);

            // Wait a moment for load? (Native logic might vary, usually prepare awaits until loaded or failed)
            // Ideally prepareRewardVideoAd promise resolves when loaded.
        }

        if (!this.isReady) return false;

        this.onRewardCallback = onReward;

        try {
            await AdMob.showRewardVideoAd();
            return true;
        } catch (e) {
            console.error('AdMob Show Error', e);
            return false;
        }
    }
}

export const Ads = new AdMobService();

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Difficulty, AppSettings, Board, MoveLogEntry } from '../types';
import { useSudokuBoard } from '../hooks/useSudokuBoard';
import { useGameSkills } from '../hooks/useGameSkills';
import { useGameTimer } from '../hooks/useGameTimer';
import { SudokuGrid } from './game/SudokuGrid';
import { GameControls } from './game/GameControls';
import { NumberPad } from './game/NumberPad';
import { WinModal } from './game/WinModal';
import { generateReplayVideo, ReplayMove } from '../utils/replay';
import { Storage } from '../utils/storage';
import { sounds } from '../utils/sound';
import { Icons } from './ui/Icons';
import { formatTimeShort } from '../utils/constants';
import { Ads, AD_IDS } from '../utils/ads';

interface SudokuGameProps {
  difficulty: Difficulty;
  levelId: number;
  onBack: () => void;
  onReturnToMenu: () => void;
  onComplete: () => void;
  onSettingsOpen: () => void;
  settings: AppSettings;
  onEarnPoints: (amount: number) => void;
  currentPoints: number;
  isSettingsOpen: boolean;
  backgroundClass: string;
  numberColor: string;
  purchasedSkills: string[];
}

export const SudokuGame: React.FC<SudokuGameProps> = ({
  difficulty,
  levelId,
  onBack,
  onReturnToMenu,
  onComplete,
  onSettingsOpen,
  settings,
  onEarnPoints,
  currentPoints,
  isSettingsOpen,
  backgroundClass,
  numberColor,
  purchasedSkills
}) => {
  const [isPaused, setIsPaused] = useState(false);
  const [showRestartConfirm, setShowRestartConfirm] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [earnedPoints, setEarnedPoints] = useState(0);

  const [isGeneratingReplay, setIsGeneratingReplay] = useState(false);
  const [replayUrl, setReplayUrl] = useState<string | null>(null);
  const [showReplay, setShowReplay] = useState(false);

  const [animatingSections, setAnimatingSections] = useState<Set<string>>(new Set());
  const [showStartHint, setShowStartHint] = useState(false);

  // Game-specific Loading Overlay (for Ad)
  const [isWatchingAd, setIsWatchingAd] = useState(false);

  // Timer hook
  const { timer, setTimer } = useGameTimer(
      settings,
      isPaused,
      isCompleted,
      isEnding,
      isSettingsOpen,
      0
  );

  const saveProgress = (currentBoard: Board, scanUsesVal?: number, revealUsesVal?: number, moveLog?: MoveLogEntry[], isPerfect: boolean = false) => {
      if (isCompleted || isEnding) return;
      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'in-progress',
          timeElapsed: timer,
          boardState: currentBoard,
          moveLog: moveLog,
          lastPlayed: Date.now(),
          scanUses: scanUsesVal !== undefined ? scanUsesVal : scanUses,
          revealUses: revealUsesVal !== undefined ? revealUsesVal : revealUses,
      }, isPerfect);
  };

  const handleSectionComplete = useCallback((sections: string[]) => {
      if (sections.length > 0) {
          setAnimatingSections(prev => {
              const next = new Set(prev);
              sections.forEach(s => next.add(s));
              return next;
          });
          setTimeout(() => {
              setAnimatingSections(prev => {
                  const next = new Set(prev);
                  sections.forEach(s => next.delete(s));
                  return next;
              });
          }, 1000);
      }
  }, []);

  const handleGameComplete = (completedBoard: Board, completedMoveLog: MoveLogEntry[], isPerfect: boolean) => {
      if (isCompleted || isEnding) return;
      setIsEnding(true);
      sounds.playWin();

      setAnimatingSections(new Set(['full-board']));
      setTimeout(() => {
          setAnimatingSections(new Set());
      }, 1500);

      let points = 0;
      switch(difficulty) {
          case Difficulty.SuperEasy: points = 5; break;
          case Difficulty.Easy: points = 10; break;
          case Difficulty.Normal: points = 15; break;
          case Difficulty.Hard: points = 20; break;
          case Difficulty.Intense: points = 30; break;
          case Difficulty.Impossible: points = 50; break;
      }

      onEarnPoints(points);
      setEarnedPoints(points);

      Storage.saveLevelProgress({
          levelId,
          difficulty,
          status: 'completed',
          timeElapsed: timer,
          boardState: completedBoard,
          moveLog: completedMoveLog,
          lastPlayed: Date.now(),
          scanUses,
          revealUses,
      }, isPerfect);

      // Grant Pepino Gift on Win
      Storage.grantPepinoGift();

      if (settings.generateReplay) {
          // Pass true to indicate auto-generation
          generateReplay();
      }

      setTimeout(() => {
          setIsCompleted(true);
          onComplete();
      }, 1500);
  };

  const {
      board,
      setBoard,
      solvedBoard,
      initialBoardRef,
      history,
      setHistory,
      moveLog,
      isPencilMode,
      setIsPencilMode,
      selectedCell,
      setSelectedCell,
      activeNumber,
      setActiveNumber,
      conflicts,
      numberCounts,
      initializeBoard,
      handleCellClick,
      handleNumberInput,
      handleUndo,
      handleErase,
      checkCompletion,
      removeNotesFromPeers
  } = useSudokuBoard({
      difficulty,
      levelId,
      settings,
      onComplete: handleGameComplete,
      onBoardChange: (newBoard, currentMoveLog) => saveProgress(newBoard, undefined, undefined, currentMoveLog),
      onSectionComplete: handleSectionComplete
  });

  const {
      scanUses,
      setScanUses,
      isScanning,
      scanCooldown,
      revealUses,
      setRevealUses,
      revealingCell,
      setRevealingCell,
      animatingCell,
      setAnimatingCell,
      isAutoAvailable,
      handleAutoFill,
      handleScan,
      handleReveal,
  } = useGameSkills({
      board,
      setBoard,
      solvedBoard,
      setHistory,
      moveLog,
      selectedCell,
      activeNumber,
      settings,
      difficulty,
      removeNotesFromPeers,
      checkCompletion,
      onSaveProgress: (b, s, r, ml) => saveProgress(b, s, r, ml),
      onSectionComplete: handleSectionComplete,
      timer
  });

  useEffect(() => {
      const progress = Storage.getLevelProgress(difficulty, levelId);
      if (progress && progress.status === 'in-progress' && progress.boardState) {
          initializeBoard(progress.boardState, progress.moveLog);
          setTimer(progress.timeElapsed);

          // Restore skills
          if (progress.scanUses !== undefined) setScanUses(progress.scanUses);
          else setScanUses(3);

          if (progress.revealUses !== undefined) setRevealUses(progress.revealUses);
          else setRevealUses(1);
      } else {
          initializeBoard();
          setTimer(0);

          // Reset skills
          setScanUses(3);
          setRevealUses(1);
      }
      setIsCompleted(false);
      setIsEnding(false);
      setIsPaused(false);
      setShowRestartConfirm(false);
      setReplayUrl(null);
      setShowReplay(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      const hintTimer = setTimeout(() => setShowStartHint(false), 5000);
      return () => clearTimeout(hintTimer);
  }, [difficulty, levelId, initializeBoard, setTimer, setScanUses, setRevealUses]);

  const handleWatchScanAd = async () => {
        setIsWatchingAd(true);
        sounds.playClick();

        // Show Ad (Refill Scans)
        const success = await Ads.showRewardVideo(AD_IDS.SCAN_REFILL, () => {
            // Reward: 1 use
            setScanUses(1);
            sounds.playWin();
        });

        setIsWatchingAd(false);

        if (!success) {
            console.log("Ad failed to show");
        }
  };

  const handleWatchRevealAd = async () => {
        setIsWatchingAd(true);
        sounds.playClick();

        // Show Ad (Refill Reveal)
        const success = await Ads.showRewardVideo(AD_IDS.REVEAL_REFILL, () => {
            // Reward: 1 use
            setRevealUses(1);
            sounds.playWin();
        });

        setIsWatchingAd(false);

        if (!success) {
            console.log("Ad failed to show");
        }
  };

  const generateReplay = () => {
        if (isGeneratingReplay || replayUrl) return;
        setIsGeneratingReplay(true);

        try {
            let cleanMoves: ReplayMove[] = [];

            // 1. Try to use real history if available
            if (moveLog.current.length > 0) {
                const finalMoveMap = new Map<string, number>();
                moveLog.current.forEach(move => {
                    // Only include moves that match final solution
                    if (solvedBoard[move.r] && solvedBoard[move.r][move.c] && move.v === solvedBoard[move.r][move.c]) {
                        finalMoveMap.set(`${move.r}-${move.c}`, move.t);
                    }
                });

                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            const t = finalMoveMap.get(`${r}-${c}`);
                            if (t !== undefined) {
                                cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t });
                            }
                        }
                    }
                }
                cleanMoves.sort((a, b) => (a.t || 0) - (b.t || 0));
            }

            // Calculate total non-fixed cells (holes)
            let totalHoles = 0;
            if (initialBoardRef.current && initialBoardRef.current.length > 0) {
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        if (!initialBoardRef.current[r][c].isFixed) totalHoles++;
                    }
                }
            }

            // 2. Smart Fallback: If incomplete moves, reconstruct a "Zen" flow
            if (cleanMoves.length < totalHoles) {
                cleanMoves = [];
                for(let r=0; r<9; r++) {
                    for(let c=0; c<9; c++) {
                        const cell = initialBoardRef.current[r][c];
                        if (!cell.isFixed) {
                            // Create artificial timestamp based on position to create a satisfying fill order
                            cleanMoves.push({ row: r, col: c, value: solvedBoard[r][c], t: (r * 9 + c) * 100 });
                        }
                    }
                }
            }

            const isDark = document.documentElement.classList.contains('dark');

            // This promise resolves when the recording is complete
            generateReplayVideo(initialBoardRef.current, cleanMoves, difficulty, levelId, isDark, timer)
                .then(url => {
                    setReplayUrl(url);
                    setIsGeneratingReplay(false);
                })
                .catch(err => {
                    console.error("Replay generation error:", err);
                    setIsGeneratingReplay(false);
                });
        } catch (e) {
            console.error("Replay preparation error:", e);
            setIsGeneratingReplay(false);
        }
  };

  const handleShareReplay = async () => {
      if (!replayUrl) return;
      try {
          const blob = await fetch(replayUrl).then(r => r.blob());
          const isMp4 = blob.type.includes('mp4');
          const ext = isMp4 ? 'mp4' : 'webm';
          const mime = isMp4 ? 'video/mp4' : 'video/webm';

          const file = new File([blob], `Oku_${difficulty}_${levelId}.${ext}`, { type: mime });
          if (navigator.share && navigator.canShare({ files: [file] })) {
              await navigator.share({
                  files: [file],
                  title: 'Oku Replay',
                  text: `I solved Level ${levelId} (${difficulty}) in ${formatTimeShort(timer)}!`
              });
          } else {
              const a = document.createElement('a');
              a.href = replayUrl;
              a.download = `sudoku_${difficulty}_${levelId}.${ext}`;
              a.click();
          }
      } catch (e) {
          console.error("Share failed", e);
      }
  };

  const handleRestart = () => {
      sounds.playClick();
      Storage.clearLevelProgress(difficulty, levelId); 
      initializeBoard(); 
      setTimer(0); 
      setScanUses(3); 
      setRevealUses(1); 
      setShowRestartConfirm(false); 
      setIsPaused(false);
      setAnimatingSections(new Set());

      setShowStartHint(true);
      setTimeout(() => setShowStartHint(false), 5000);
  };

  const handleBackgroundClick = (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) {
          setSelectedCell(null);
      }
  };

  // Determine if erase is possible for the selected cell (value or notes)
  const canErase = !!selectedCell && (() => {
      const [r, c] = selectedCell;
      const cell = board[r][c];
      return !cell.isFixed && (cell.value !== null || cell.notes.length > 0);
  })();

  // Memoize click handlers to avoid passing new functions on every timer tick
  const onCellClickWrapper = useCallback((e: React.MouseEvent, r: number, c: number) => {
      handleCellClick(r, c, isPaused, isCompleted);
  }, [handleCellClick, isPaused, isCompleted]);

  const onNumberClickWrapper = useCallback((e: React.MouseEvent, n: number) => {
      handleNumberInput(n, isPaused, isCompleted);
  }, [handleNumberInput, isPaused, isCompleted]);

  return (
    <>
      <div className="w-full flex justify-center px-6 pt-4 pb-4 relative z-40 shrink-0">
          <div className="w-full max-w-md flex items-center justify-between relative">
              {/* Left Column: Back Button */}
              <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200/50 transition -ml-2 text-t-icon relative z-30">
                  <Icons.Back className="w-6 h-6" />
              </button>

              {/* Center Column: Title & Timer - Absolute Centered */}
              <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                  {settings.showTimer ? (
                      <span className="text-xl font-bold text-t-primary tabular-nums leading-none">{formatTimeShort(timer)}</span>
                  ) : (
                      <span className="text-xl font-bold text-t-primary leading-none">Level {levelId}</span>
                  )}
                  <span className="text-[10px] font-bold text-stone-600 dark:text-stone-400 uppercase tracking-widest mt-1">
                    {difficulty} {settings.showTimer && `• ${levelId}`}
                  </span>
              </div>

              {/* Right Column: Actions */}
              <div className="flex items-center gap-1 relative z-30 -mr-2">
                  <button onClick={() => { sounds.playClick(); setIsPaused(true); }} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Pause className="w-6 h-6" />
                  </button>
                  <button onClick={onSettingsOpen} className="p-2 rounded-full hover:bg-stone-200/50 transition text-t-icon">
                      <Icons.Settings className="w-6 h-6" />
                  </button>
              </div>
          </div>
      </div>

      <div 
          className="flex-1 w-full flex flex-col items-center justify-start relative cursor-default" 
          onClick={handleBackgroundClick}
      >
         <div className="contents">
            <SudokuGrid 
                board={board}
                selectedCell={selectedCell}
                activeNumber={activeNumber}
                conflicts={conflicts}
                revealingCell={revealingCell}
                animatingCell={animatingCell}
                isScanning={isScanning}
                animatingSections={animatingSections}
                settings={settings}
                numberColor={numberColor}
                onCellClick={onCellClickWrapper}
            />
         </div>

         {/* Number Pad - Wider [500px] to match grid */}
         <div className="w-full max-w-[500px] px-2 mt-4 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <NumberPad 
                 activeNumber={activeNumber}
                 numberCounts={numberCounts}
                 isPencilMode={isPencilMode}
                 numberColor={numberColor}
                 onNumberClick={onNumberClickWrapper}
             />
         </div>

         {/* Game Controls - Increased spacing (mt-10) */}
         <div className="w-full max-w-md px-6 mt-10 relative z-[100]" onClick={(e) => e.stopPropagation()}>
             <GameControls 
                 canUndo={history.length > 0}
                 canErase={canErase}
                 isPencilMode={isPencilMode}
                 onUndo={(e) => handleUndo(isPaused, isCompleted)}
                 onErase={(e) => handleErase(isPaused, isCompleted)}
                 onTogglePencil={() => { sounds.playClick(); setIsPencilMode(!isPencilMode); }}
                 purchasedSkills={purchasedSkills}
                 isAutoAvailable={isAutoAvailable}
                 scanUses={scanUses}
                 isScanning={isScanning}
                 scanCooldown={scanCooldown}
                 revealUses={revealUses}
                 revealingCell={revealingCell}
                 onAutoFill={() => handleAutoFill(purchasedSkills)}
                 onScan={() => handleScan(isPaused, isCompleted)}
                 onWatchScanAd={handleWatchScanAd}
                 onReveal={() => handleReveal(isPaused, isCompleted)}
                 onWatchRevealAd={handleWatchRevealAd}
                 timer={timer}
             />
         </div>

         {/* Deselect Text - Increased spacing (mt-8) */}
         <div className={`mt-8 mb-4 pointer-events-none transition-opacity duration-1000 ${showStartHint ? 'opacity-100' : 'opacity-0'}`}>
             <span className="text-xs font-light text-stone-400 dark:text-stone-500 tracking-wide">Tap here to deselect</span>
         </div>
      </div>

      {(isPaused || showRestartConfirm) && (
          <div className="fixed inset-0 bg-stone-50/90 dark:bg-stone-900/90 backdrop-blur-sm z-[100] flex items-center justify-center animate-fade-in">
              {!showRestartConfirm ? (
                  <div className="flex flex-col gap-4 w-48 animate-pop">
                    <h2 className="text-2xl font-bold text-stone-800 dark:text-t-primary mb-4 text-center">Game Paused</h2>
                    <button onClick={() => { sounds.playClick(); setIsPaused(false); }} className="flex items-center justify-center gap-2 p-4 bg-stone-800 text-white dark:bg-blue-600 dark:text-white rounded-xl shadow-lg active:scale-95 transition hover:opacity-90">
                        <Icons.Play className="w-5 h-5 fill-current" /> Resume
                    </button>
                    <button onClick={() => { sounds.playClick(); setShowRestartConfirm(true); }} className="flex items-center justify-center gap-2 p-4 bg-white text-stone-800 border border-stone-200 dark:bg-t-surface dark:text-t-primary dark:border-t-border rounded-xl active:scale-95 transition hover:bg-stone-50 dark:hover:bg-t-surface-sec">
                        <Icons.Reset className="w-5 h-5" /> Restart Level
                    </button>
                    <button onClick={() => { sounds.playClick(); onBack(); }} className="flex items-center justify-center gap-2 p-4 text-stone-500 hover:text-stone-800 dark:text-t-secondary dark:hover:text-t-primary transition font-medium">
                        Quit Game
                    </button>
                  </div>
              ) : (
                  <div className="bg-white dark:bg-t-surface p-6 rounded-2xl shadow-xl w-full max-w-sm text-center animate-pop">
                     <h3 className="text-lg font-bold text-stone-800 dark:text-t-primary mb-2">Restart Level?</h3>
                     <p className="text-stone-500 dark:text-t-secondary text-sm mb-6">Are you sure? This will reset your progress on this level.</p>
                     <div className="flex gap-3">
                         <button onClick={() => { sounds.playClick(); setShowRestartConfirm(false); }} className="flex-1 py-3 text-stone-600 bg-stone-100 dark:bg-t-surface-sec dark:text-t-primary rounded-xl font-medium active:scale-95 transition">Cancel</button>
                         <button onClick={handleRestart} className="flex-1 py-3 text-white bg-red-500 rounded-xl font-medium shadow-md active:scale-95 transition">Restart</button>
                     </div>
                  </div>
              )}
          </div>
      )}

      {isWatchingAd && (
          <div className="fixed inset-0 z-[150] bg-black/60 backdrop-blur-md flex items-center justify-center animate-fade-in">
              <div className="bg-t-surface p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4 animate-pop">
                  <div className="w-10 h-10 border-4 border-stone-200 border-t-blue-500 rounded-full animate-spin"></div>
                  <p className="font-bold text-t-primary">Loading Reward...</p>
              </div>
          </div>
      )}

      {isCompleted && (
          <WinModal 
              difficulty={difficulty}
              levelId={levelId}
              timer={timer}
              points={earnedPoints}
              isGeneratingReplay={isGeneratingReplay}
              replayUrl={replayUrl}
              showReplay={showReplay}
              generateReplayEnabled={settings.generateReplay}
              onReplay={(e) => { e.stopPropagation(); setShowReplay(true); }}
              onShareReplay={handleShareReplay}
              onCloseReplay={() => setShowReplay(false)}
              onGenerateReplay={generateReplay}
              onBack={onBack}
              onReturnToMenu={onReturnToMenu}
          />
      )}
    </>
  );
};

import React from 'react';
import { Icons } from '../ui/Icons';
import { sounds } from '../../utils/sound';

interface GameControlsProps {
    canUndo: boolean;
    canErase: boolean;
    isPencilMode: boolean;
    onUndo: (e: React.MouseEvent) => void;
    onErase: (e: React.MouseEvent) => void;
    onTogglePencil: (e: React.MouseEvent) => void;
    purchasedSkills: string[];
    // Skill specific props
    isAutoAvailable: boolean;
    scanUses: number;
    isScanning: boolean;
    scanCooldown: boolean;
    revealUses: number;
    revealingCell: {r: number, c: number} | null;
    onAutoFill: (e: React.MouseEvent) => void;
    onScan: (e: React.MouseEvent) => void;
    onWatchScanAd: (e: React.MouseEvent) => void;
    onReveal: (e: React.MouseEvent) => void;
    onWatchRevealAd: (e: React.MouseEvent) => void;
    timer: number;
}

export const GameControls: React.FC<GameControlsProps> = ({
    canUndo,
    canErase,
    isPencilMode,
    onUndo,
    onErase,
    onTogglePencil,
    purchasedSkills,
    isAutoAvailable,
    scanUses,
    isScanning,
    scanCooldown,
    revealUses,
    revealingCell,
    onAutoFill,
    onScan,
    onWatchScanAd,
    onReveal,
    onWatchRevealAd,
    timer
}) => {
    // Helper for common enabled/disabled styles
    const getBaseButtonStyle = (isEnabled: boolean) => 
        isEnabled 
            ? 'text-stone-900 dark:text-stone-100 cursor-pointer hover:brightness-95 active:scale-95' 
            : 'text-stone-300 dark:text-stone-600 cursor-not-allowed';

    // Removed borders from base container styles
    const getBaseContainerStyle = (isEnabled: boolean) => 
        isEnabled
            ? 'bg-white dark:bg-stone-800'
            : 'bg-t-surface-sec dark:bg-stone-800/50';

    const revealTimeLeft = Math.max(0, 60 - timer);
    const isRevealLocked = revealTimeLeft > 0;

    return (
        <div className="flex justify-between w-full relative">
            {/* Reveal Skill Button */}
            {purchasedSkills.includes('skill-reveal') && (
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            if (revealUses > 0) onReveal(e);
                            else onWatchRevealAd(e);
                        }} 
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(!revealingCell && !isRevealLocked)}`}
                        disabled={!!revealingCell || isRevealLocked}
                    >
                    {/* Removed border class */}
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(!isRevealLocked)}`}>
                        {isRevealLocked ? (
                            <div className="w-5 h-5 flex items-center justify-center">
                                <span className="text-[10px] font-bold text-stone-400 font-mono leading-none">{revealTimeLeft}s</span>
                            </div>
                        ) : (
                            <Icons.Reveal className={`w-5 h-5 ${revealUses > 0 ? 'text-purple-600 dark:text-purple-400' : (revealUses === 0 ? 'text-blue-500' : 'text-stone-300 dark:text-stone-600')}`} />
                        )}

                        {/* Larger Badge for Reveal - Moved to -top-4 -right-4 */}
                        <div className={`absolute -top-4 -right-4 w-7 h-7 rounded-full flex items-center justify-center text-base font-bold leading-none shadow-sm z-10 ${revealUses > 0 && !isRevealLocked ? 'bg-blue-600 text-white' : (revealUses === 0 && !isRevealLocked ? 'bg-blue-600 text-white' : 'bg-stone-300 text-white dark:bg-stone-600')}`}>
                                {revealUses > 0 ? revealUses : (isRevealLocked ? '+' : <span className="text-[10px]">Ad</span>)}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Reveal</span>
                </button>
            )}

            {/* Scan Skill Button */}
            {purchasedSkills.includes('skill-scan') && (
                    <button 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            if (scanUses > 0) onScan(e);
                            else onWatchScanAd(e);
                        }} 
                        // Enabled if uses > 0 OR if we can watch an ad (uses == 0)
                        // Disabled only if active cooldown/scanning
                        className={`flex flex-col items-center gap-1 transition relative ${getBaseButtonStyle(!scanCooldown && !isScanning)}`}
                        disabled={scanCooldown || isScanning}
                    >
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 relative ${getBaseContainerStyle(!scanCooldown && !isScanning)}`}>
                        <Icons.Scan className={`w-5 h-5 ${scanUses > 0 && !scanCooldown && !isScanning ? 'text-red-600 dark:text-red-400' : (scanUses === 0 ? 'text-blue-500' : 'text-stone-300 dark:text-stone-600')}`} />

                        {/* Badge for Scan */}
                        <div className={`absolute -top-4 -right-4 w-7 h-7 rounded-full flex items-center justify-center text-base font-bold leading-none shadow-sm z-10 ${scanUses > 0 ? 'bg-blue-600 text-white' : 'bg-blue-600 text-white'}`}>
                            {scanUses > 0 ? scanUses : <span className="text-[10px]">Ad</span>}
                        </div>
                    </div>
                    <span className="text-sm font-medium">Scan</span>
                </button>
            )}

            {/* Auto Skill Button */}
            {purchasedSkills.includes('skill-auto') && (
                <button 
                    onClick={(e) => { e.stopPropagation(); onAutoFill(e); }} 
                    className={`flex flex-col items-center gap-1 transition relative active:scale-95 ${isAutoAvailable ? 'cursor-pointer text-amber-700 dark:text-amber-400' : 'cursor-not-allowed text-stone-300 dark:text-stone-600'}`}
                    disabled={!isAutoAvailable}
                >
                    {/* Removed borders and rings */}
                    <div className={`p-3 rounded-full shadow-sm transition-all duration-300 ${
                        isAutoAvailable 
                        ? 'bg-amber-100 dark:bg-amber-900/30' 
                        : 'bg-t-surface-sec dark:bg-stone-800/50'
                    }`}>
                        <Icons.Auto className={`w-5 h-5 ${isAutoAvailable ? 'text-amber-600 dark:text-amber-400 animate-pulse' : 'text-stone-300 dark:text-stone-600'}`} />
                    </div>
                    <span className="text-sm font-medium">Auto</span>
                </button>
            )}

            {/* UNDO BUTTON */}
            <button 
                onClick={onUndo} 
                disabled={!canUndo}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canUndo)}`}
            >
                <div className={`p-3 rounded-full shadow-sm transition-colors ${getBaseContainerStyle(canUndo)}`}>
                    <Icons.Undo className={`w-5 h-5 ${canUndo ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Undo</span>
            </button>

            {/* PENCIL BUTTON */}
            <button 
                onClick={onTogglePencil} 
                className={`flex flex-col items-center gap-1 active:scale-95 transition cursor-pointer hover:brightness-95 ${isPencilMode ? 'text-blue-700 dark:text-blue-300' : 'text-stone-900 dark:text-stone-100'}`}
            >
                {/* Removed borders */}
                <div className={`p-3 rounded-full shadow-sm transition-colors ${
                    isPencilMode 
                    ? 'bg-blue-100 dark:bg-blue-900/40' 
                    : 'bg-white dark:bg-stone-800'
                }`}>
                    <Icons.Pencil className={`w-5 h-5 ${isPencilMode ? 'text-blue-600 dark:text-blue-400' : 'text-stone-700 dark:text-stone-300'}`} />
                </div>
                <span className="text-sm font-medium">Pencil</span>
            </button>

            {/* ERASE BUTTON */}
            <button 
                onClick={onErase} 
                disabled={!canErase}
                className={`flex flex-col items-center gap-1 transition ${getBaseButtonStyle(canErase)}`}
            >
                <div className={`p-3 rounded-full shadow-sm transition-colors ${getBaseContainerStyle(canErase)}`}>
                    <Icons.Erase className={`w-5 h-5 ${canErase ? 'text-stone-700 dark:text-stone-300' : 'text-stone-300 dark:text-stone-600'}`} />
                </div>
                <span className="text-sm font-medium">Erase</span>
            </button>
        </div>
    );
};
